#!/usr/bin/env python3
"""Apply small compatibility patches to the vendored Speakeasy image."""
from __future__ import annotations

import importlib.util
from pathlib import Path


def _speakeasy_root() -> Path:
    spec = importlib.util.find_spec("speakeasy")
    if not spec or not spec.submodule_search_locations:
        raise RuntimeError("speakeasy package not found")
    return Path(next(iter(spec.submodule_search_locations))).resolve()


def _insert_once(text: str, needle: str, marker: str, block: str, path: Path) -> str:
    if needle in text:
        return text
    if marker not in text:
        raise RuntimeError(f"patch anchor not found in {path}: {marker.strip()}")
    return text.replace(marker, block + marker, 1)


def patch_fls_get_value2() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")

    marker = "    @apihook('EncodePointer', argc=1)\n"
    handler = """    @apihook('FlsGetValue2', argc=1)
    def FlsGetValue2(self, emu, argv, ctx={}):
        '''
        PVOID FlsGetValue2(
          DWORD dwFlsIndex
        );
        '''
        dwFlsIndex, = argv
        dwFlsIndex &= 0xFFFFFFFF
        rv = 0

        thread = emu.get_current_thread()
        fls = thread.get_fls()

        if dwFlsIndex < len(fls):
            rv = fls[dwFlsIndex]

        return rv

"""
    text = _insert_once(text, "def FlsGetValue2(", marker, handler, kernel32)
    kernel32.write_text(text, encoding="utf-8")


def patch_get_temp_path2() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")

    marker = "    @apihook('SetPriorityClass', argc=2)\n"
    handler = r"""    def _get_temp_path2_value(self, emu):
        env = emu.get_env()

        def get_env(*names):
            for name in names:
                for key in (name, name.lower(), name.upper()):
                    val = env.get(key)
                    if val:
                        return val
            return ''

        tempdir = (
            get_env('TMP')
            or get_env('TEMP')
            or get_env('USERPROFILE')
            or get_env('WINDIR')
            or get_env('SystemRoot')
            or 'C:\\Windows'
        )
        if not tempdir.endswith(('\\', '/')):
            tempdir += '\\'
        return tempdir

    def _GetTempPath2(self, emu, argv, ctx={}):
        buffer_length, buffer = argv
        buffer_length &= 0xFFFFFFFF
        cw = self.get_char_width(ctx)
        tempdir = self._get_temp_path2_value(emu)
        required = len(tempdir) + 1

        if buffer and buffer_length >= required:
            if cw == 2:
                out = tempdir.encode('utf-16le') + b'\x00\x00'
            else:
                out = tempdir.encode('utf-8') + b'\x00'
            self.mem_write(buffer, out)
            argv[1] = tempdir
            emu.set_last_error(windefs.ERROR_SUCCESS)
            return len(tempdir)

        if buffer_length < required:
            emu.set_last_error(windefs.ERROR_INSUFFICIENT_BUFFER)
            return required

        return 0

    @apihook('GetTempPath2', argc=2)
    def GetTempPath2(self, emu, argv, ctx={}):
        '''
        DWORD GetTempPath2(
          DWORD  BufferLength,
          LPTSTR Buffer
        );
        '''
        return self._GetTempPath2(emu, argv, ctx)

"""
    text = _insert_once(text, "def GetTempPath2(", marker, handler, kernel32)
    kernel32.write_text(text, encoding="utf-8")


def patch_get_temp_path_guard() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")
    if "Speakeasy overlay: tolerate invalid GetTempPath buffers" in text:
        return

    old = """    @apihook('GetTempPath', argc=2)
    def GetTempPath(self, emu, argv, ctx={}):
        '''
        DWORD GetTempPathA(
        DWORD nBufferLength,
        LPSTR lpBuffer
        );
        '''

        nBufferLength, lpBuffer = argv
        rv = 0
        cw = self.get_char_width(ctx)
        tempdir = emu.get_env().get('temp', 'C:\\\\Windows\\\\temp\\\\')
        if cw == 2:
            new = (tempdir).encode('utf-16le') + b'\\x00\\x00'
        else:
            new = (tempdir).encode('utf-8') + b'\\x00'
        rv = len(tempdir)
        if lpBuffer:
            argv[1] = tempdir
            self.mem_write(lpBuffer, new)
        return rv

"""
    new = """    @apihook('GetTempPath', argc=2)
    def GetTempPath(self, emu, argv, ctx={}):
        '''
        DWORD GetTempPathA(
        DWORD nBufferLength,
        LPSTR lpBuffer
        );
        '''

        nBufferLength, lpBuffer = argv
        cw = self.get_char_width(ctx)
        tempdir = emu.get_env().get('temp', 'C:\\\\Windows\\\\Temp\\\\') or 'C:\\\\Windows\\\\Temp\\\\'
        if not tempdir.endswith('\\\\'):
            tempdir += '\\\\'
        raw = tempdir.encode('utf-16le') + b'\\x00\\x00' if cw == 2 else tempdir.encode('utf-8') + b'\\x00'
        if lpBuffer and nBufferLength:
            try:
                limit = max(0, (nBufferLength & 0xFFFFFFFF) * cw)
                self.mem_write(lpBuffer, raw[:limit] if limit else raw)
                argv[1] = tempdir
            except Exception:
                # Speakeasy overlay: tolerate invalid GetTempPath buffers.
                pass
        return len(tempdir)

"""
    if old not in text:
        raise RuntimeError(f"GetTempPath patch anchor not found in {kernel32}")
    kernel32.write_text(text.replace(old, new, 1), encoding="utf-8")


def patch_co_create_guid() -> None:
    ole32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "ole32.py"
    text = ole32.read_text(encoding="utf-8")

    marker = "    @apihook('CoUninitialize', argc=0)\n"
    handler = """    @apihook('CoCreateGuid', argc=1)
    def CoCreateGuid(self, emu, argv, ctx={}):
        '''
        HRESULT CoCreateGuid(
          GUID *pguid
        );
        '''
        pguid, = argv

        if not pguid:
            return 0x80070057

        counter = (getattr(self, '_sx_guid_counter', 0) + 1) & 0xFFFFFFFF
        self._sx_guid_counter = counter
        guid = (
            b'VRSE'
            + counter.to_bytes(4, 'little')
            + b'\\x80\\x00'
            + b'\\x00\\xaa\\x00\\x38\\x9b\\x71'
        )
        self.mem_write(pguid, guid)
        argv[0] = guid.hex()

        return windefs.S_OK

"""
    text = _insert_once(text, "def CoCreateGuid(", marker, handler, ole32)
    ole32.write_text(text, encoding="utf-8")


def patch_ole32_string_from_guid2() -> None:
    ole32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "ole32.py"
    text = ole32.read_text(encoding="utf-8")

    marker = "    @apihook('CoUninitialize', argc=0)\n"
    handler = """    @apihook('StringFromGUID2', argc=3)
    def StringFromGUID2(self, emu, argv, ctx={}):
        '''
        int StringFromGUID2(
          REFGUID rguid,
          LPOLESTR lpsz,
          int cchMax
        );
        '''
        rguid, lpsz, cchMax = argv
        if not rguid or not lpsz:
            return 0

        raw = self.mem_read(rguid, 16)
        d1 = int.from_bytes(raw[0:4], 'little')
        d2 = int.from_bytes(raw[4:6], 'little')
        d3 = int.from_bytes(raw[6:8], 'little')
        guid = '{%08X-%04X-%04X-%02X%02X-%s}' % (
            d1,
            d2,
            d3,
            raw[8],
            raw[9],
            raw[10:16].hex().upper(),
        )
        required = len(guid) + 1
        if cchMax < required:
            return 0
        self.write_mem_string(guid, lpsz, 2)
        argv[1] = guid
        return required

    @apihook('IIDFromString', argc=2)
    def IIDFromString(self, emu, argv, ctx={}):
        '''
        HRESULT IIDFromString(
          LPCOLESTR lpsz,
          LPIID     lpiid
        );
        '''
        lpsz, lpiid = argv
        if not lpiid:
            return 0x80070057
        text = self.read_mem_string(lpsz, 2).strip('{}') if lpsz else ''
        parts = text.split('-')
        raw = b'\\x00' * 16
        try:
            if len(parts) == 5:
                d1 = int(parts[0], 16).to_bytes(4, 'little')
                d2 = int(parts[1], 16).to_bytes(2, 'little')
                d3 = int(parts[2], 16).to_bytes(2, 'little')
                d4 = bytes.fromhex(parts[3] + parts[4])
                raw = d1 + d2 + d3 + d4
        except Exception:
            raw = b'\\x00' * 16
        self.mem_write(lpiid, raw)
        return 0

    @apihook('CLSIDFromString', argc=2)
    def CLSIDFromString(self, emu, argv, ctx={}):
        return self.IIDFromString(emu, argv, ctx)

    @apihook('CLSIDFromProgID', argc=2)
    def CLSIDFromProgID(self, emu, argv, ctx={}):
        lpszProgID, lpclsid = argv
        if lpszProgID:
            try:
                argv[0] = self.read_mem_string(lpszProgID, 2)
            except Exception:
                pass
        if lpclsid:
            raw = bytes.fromhex('00021401 0000 0000 c000 000000000046'.replace(' ', ''))
            self.mem_write(lpclsid, raw)
        return 0

    @apihook('CLSIDFromProgIDEx', argc=2)
    def CLSIDFromProgIDEx(self, emu, argv, ctx={}):
        return self.CLSIDFromProgID(emu, argv, ctx)

"""
    text = _insert_once(text, "def StringFromGUID2(", marker, handler, ole32)
    ole32.write_text(text, encoding="utf-8")


def patch_ole32_stream_helpers() -> None:
    ole32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "ole32.py"
    text = ole32.read_text(encoding="utf-8")

    marker = "    @apihook('CoUninitialize', argc=0)\n"
    handler = """    @apihook('OleUninitialize', argc=0)
    def OleUninitialize(self, emu, argv, ctx={}):
        return None

    @apihook('CreateStreamOnHGlobal', argc=3)
    def CreateStreamOnHGlobal(self, emu, argv, ctx={}):
        '''
        HRESULT CreateStreamOnHGlobal(
          HGLOBAL  hGlobal,
          BOOL     fDeleteOnRelease,
          LPSTREAM *ppstm
        );
        '''
        hGlobal, fDeleteOnRelease, ppstm = argv
        if ppstm:
            stream = self.mem_alloc(0x100, tag='api.ole32.IStream')
            self.mem_write(stream, b'\\x00' * 0x100)
            self.mem_write(ppstm, stream.to_bytes(emu.get_ptr_size(), 'little'))
        return windefs.S_OK

    @apihook('CreateILockBytesOnHGlobal', argc=3)
    def CreateILockBytesOnHGlobal(self, emu, argv, ctx={}):
        '''
        HRESULT CreateILockBytesOnHGlobal(
          HGLOBAL      hGlobal,
          BOOL         fDeleteOnRelease,
          LPLOCKBYTES  *pplkbyt
        );
        '''
        hGlobal, fDeleteOnRelease, pplkbyt = argv
        if pplkbyt:
            lockbytes = self.mem_alloc(0x100, tag='api.ole32.ILockBytes')
            self.mem_write(lockbytes, b'\\x00' * 0x100)
            self.mem_write(pplkbyt, lockbytes.to_bytes(emu.get_ptr_size(), 'little'))
        return windefs.S_OK

    @apihook('GetHGlobalFromILockBytes', argc=2)
    def GetHGlobalFromILockBytes(self, emu, argv, ctx={}):
        plkbyt, phglobal = argv
        if phglobal:
            self.mem_write(phglobal, (0).to_bytes(emu.get_ptr_size(), 'little'))
        return windefs.S_OK

    @apihook('StgCreateDocfileOnILockBytes', argc=5)
    def StgCreateDocfileOnILockBytes(self, emu, argv, ctx={}):
        plkbyt, grfMode, reserved, riid, ppstgOpen = argv
        if ppstgOpen:
            storage = self.mem_alloc(0x100, tag='api.ole32.IStorage')
            self.mem_write(storage, b'\\x00' * 0x100)
            self.mem_write(ppstgOpen, storage.to_bytes(emu.get_ptr_size(), 'little'))
        return windefs.S_OK

    @apihook('StgOpenStorageOnILockBytes', argc=6)
    def StgOpenStorageOnILockBytes(self, emu, argv, ctx={}):
        plkbyt, pstgPriority, grfMode, snbExclude, reserved, ppstgOpen = argv
        if ppstgOpen:
            storage = self.mem_alloc(0x100, tag='api.ole32.IStorage')
            self.mem_write(storage, b'\\x00' * 0x100)
            self.mem_write(ppstgOpen, storage.to_bytes(emu.get_ptr_size(), 'little'))
        return windefs.S_OK

    def _sx_write_multi_qi_success(self, emu, rgmqResults, cmq):
        if not rgmqResults or not cmq:
            return
        ptr_size = emu.get_ptr_size()
        entry_size = ptr_size + ptr_size + 4
        for i in range(min(cmq & 0xFFFFFFFF, 16)):
            base = rgmqResults + (i * entry_size)
            try:
                obj = self.mem_alloc(ptr_size, tag='api.ole32.MULTI_QI.pItf')
                self.mem_write(obj, (0).to_bytes(ptr_size, 'little'))
                self.mem_write(base + ptr_size, obj.to_bytes(ptr_size, 'little'))
                self.mem_write(base + (ptr_size * 2), windefs.S_OK.to_bytes(4, 'little'))
            except Exception:
                pass

    @apihook('CoGetInstanceFromIStorage', argc=7)
    def CoGetInstanceFromIStorage(self, emu, argv, ctx={}):
        pServerInfo, pClsid, punkOuter, dwClsCtx, pStg, cmq, rgmqResults = argv
        self._sx_write_multi_qi_success(emu, rgmqResults, cmq)
        return windefs.S_OK

    @apihook('CoGetInstanceFromFile', argc=8)
    def CoGetInstanceFromFile(self, emu, argv, ctx={}):
        pServerInfo, pClsid, punkOuter, dwClsCtx, grfMode, pwszName, cmq, rgmqResults = argv
        if pwszName:
            try:
                argv[5] = self.read_mem_string(pwszName, 2)
            except Exception:
                pass
        self._sx_write_multi_qi_success(emu, rgmqResults, cmq)
        return windefs.S_OK

    @apihook('CoTaskMemAlloc', argc=1)
    def CoTaskMemAlloc(self, emu, argv, ctx={}):
        size, = argv
        size = max(1, size & 0xFFFFFFFF)
        ptr = self.mem_alloc(size, tag='api.ole32.CoTaskMemAlloc')
        self.mem_write(ptr, b'\\x00' * size)
        return ptr

    @apihook('CoTaskMemFree', argc=1)
    def CoTaskMemFree(self, emu, argv, ctx={}):
        return None

    @apihook('CoRegisterClassObject', argc=5)
    def CoRegisterClassObject(self, emu, argv, ctx={}):
        rclsid, pUnk, dwClsContext, flags, lpdwRegister = argv
        if lpdwRegister:
            self.mem_write(lpdwRegister, (1).to_bytes(4, 'little'))
        return windefs.S_OK

    @apihook('GetHGlobalFromStream', argc=2)
    def GetHGlobalFromStream(self, emu, argv, ctx={}):
        pstm, phglobal = argv
        if phglobal:
            self.mem_write(phglobal, (0).to_bytes(emu.get_ptr_size(), 'little'))
        return windefs.S_OK

"""
    text = _insert_once(text, "def CreateStreamOnHGlobal(", marker, handler, ole32)
    ole32.write_text(text, encoding="utf-8")


