def patch_kernel32_wait_for_multiple_objects_ex() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")

    marker_single = "    @apihook('WaitForSingleObject', argc=2)\n"
    handler_single = """    def _sx_pop_pending_thread_run(self, emu, hHandle):
        try:
            obj = self.get_object_from_handle(hHandle)
        except Exception:
            obj = None
        if not obj or obj.__class__.__name__.lower() != 'thread':
            return None, obj
        queue = getattr(emu, 'run_queue', [])
        for idx, run in enumerate(list(queue)):
            if getattr(run, 'thread', None) is obj:
                try:
                    return queue.pop(idx), obj
                except Exception:
                    return run, obj
        return None, obj

    def _sx_wait_for_handle(self, emu, hHandle, dwMilliseconds, argv):
        dwMilliseconds &= 0xFFFFFFFF
        if dwMilliseconds == 0:
            pending, obj = self._sx_pop_pending_thread_run(emu, hHandle)
            if pending is not None:
                try:
                    emu.run_queue.insert(0, pending)
                except Exception:
                    pass
                return windefs.WAIT_TIMEOUT
            return windefs.WAIT_OBJECT_0

        pending, obj = self._sx_pop_pending_thread_run(emu, hHandle)
        if pending is not None:
            # Speakeasy cannot safely re-enter the emulator from an API hook for
            # arbitrary thread starts. Consume the queued thread on a blocking
            # wait so the runtime does not observe "wait succeeded" and then run
            # that same thread later in the wrong context. This models join
            # completion conservatively without fabricating delayed execution.
            try:
                setattr(obj, '_sx_joined_at_wait', True)
            except Exception:
                pass
            return windefs.WAIT_OBJECT_0

        if dwMilliseconds in (1, 2, 10):
            return windefs.WAIT_TIMEOUT
        return windefs.WAIT_OBJECT_0

    @apihook('WaitForSingleObjectEx', argc=3)
    def WaitForSingleObjectEx(self, emu, argv, ctx={}):
        '''
        DWORD WaitForSingleObjectEx(
          HANDLE hHandle,
          DWORD  dwMilliseconds,
          BOOL   bAlertable
        );
        '''
        hHandle, dwMilliseconds, bAlertable = argv
        return self._sx_wait_for_handle(emu, hHandle, dwMilliseconds, argv)

"""
    text = _insert_once(text, "def WaitForSingleObjectEx(", marker_single, handler_single, kernel32)

    old_single = """    @apihook('WaitForSingleObject', argc=2)
    def WaitForSingleObject(self, emu, argv, ctx={}):
        '''
        DWORD WaitForSingleObject(
        HANDLE hHandle,
        DWORD  dwMilliseconds
        );
        '''
        hHandle, dwMilliseconds = argv

        # TODO
        if dwMilliseconds == 1:
            rv = windefs.WAIT_TIMEOUT
        else:
            rv = windefs.WAIT_OBJECT_0

        return rv

"""
    new_single = """    @apihook('WaitForSingleObject', argc=2)
    def WaitForSingleObject(self, emu, argv, ctx={}):
        '''
        DWORD WaitForSingleObject(
        HANDLE hHandle,
        DWORD  dwMilliseconds
        );
        '''
        hHandle, dwMilliseconds = argv
        return self._sx_wait_for_handle(emu, hHandle, dwMilliseconds, argv)

"""
    if old_single in text:
        text = text.replace(old_single, new_single, 1)
    elif "_sx_wait_for_handle" not in text:
        raise RuntimeError(f"WaitForSingleObject patch anchor not found in {kernel32}")

    marker = "    @apihook('WaitForMultipleObjects', argc=4)\n"
    handler = """    @apihook('WaitForMultipleObjectsEx', argc=5)
    def WaitForMultipleObjectsEx(self, emu, argv, ctx={}):
        '''
        DWORD WaitForMultipleObjectsEx(
          DWORD  nCount,
          const HANDLE *lpHandles,
          BOOL   bWaitAll,
          DWORD  dwMilliseconds,
          BOOL   bAlertable
        );
        '''
        nCount, lpHandles, bWaitAll, dwMilliseconds, bAlertable = argv
        dwMilliseconds &= 0xFFFFFFFF

        if nCount == 1 and lpHandles:
            try:
                hnd = int.from_bytes(self.mem_read(lpHandles, emu.get_ptr_size()), 'little')
                return self._sx_wait_for_handle(emu, hnd, dwMilliseconds, argv)
            except Exception:
                pass
        if dwMilliseconds == 0xFFFFFFFF:
            return windefs.WAIT_OBJECT_0
        return windefs.WAIT_TIMEOUT

"""
    text = _insert_once(text, "def WaitForMultipleObjectsEx(", marker, handler, kernel32)
    kernel32.write_text(text, encoding="utf-8")


