    @apihook('GetSecurityInfo', argc=8, conv=_arch.CALL_CONV_STDCALL)
    def GetSecurityInfo(self, emu, argv, ctx={}):
        handle, object_type, security_info, ppsid_owner, ppsid_group, ppDacl, ppSacl, ppSecurityDescriptor = argv
        sid = self._sx_system_sid()
