    @apihook('SetNamedSecurityInfo', argc=7, conv=_arch.CALL_CONV_STDCALL)
    def SetNamedSecurityInfo(self, emu, argv, ctx={}):
        pObjectName, ObjectType, SecurityInfo, psidOwner, psidGroup, pDacl, pSacl = argv
