def patch_advapi_crypto_key_lifecycle() -> None:
    advapi32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "advapi32.py"
    text = advapi32.read_text(encoding="utf-8")

    marker = "    @apihook('CryptDeriveKey', argc=5)\n"
    handler = """    def _sx_make_hcryptkey(self, emu, algid, keylen):
        ptrsz = emu.get_ptr_size()
        keylen = max(1, min(int(keylen or 16), 256))

        hkey = self.win.HCRYPTKEY(ptrsz)
        hkey.Algid = algid
        hkey.keylen = keylen
        hkey.keyp = self.mem_alloc(keylen, tag='api.advapi32.crypt.key.data')
        self.mem_write(hkey.keyp, bytes((i & 0xFF for i in range(keylen))))

        hkeyp = self.mem_alloc(hkey.sizeof(), tag='api.advapi32.crypt.hkey')
        self.mem_write(hkeyp, hkey.get_bytes())
        return hkeyp

    @apihook('CryptGenKey', argc=4)
    def CryptGenKey(self, emu, argv, ctx={}):
        '''
        BOOL CryptGenKey(
          HCRYPTPROV hProv,
          ALG_ID     Algid,
          DWORD      dwFlags,
          HCRYPTKEY  *phKey
        );
        '''
        hProv, Algid, dwFlags, phKey = argv
        if not phKey:
            return 0

        key_bits = (dwFlags >> 16) & 0xFFFF
        keylen = (key_bits // 8) if key_bits else 16
        hkeyp = self._sx_make_hcryptkey(emu, Algid, keylen)
        self.mem_write(phKey, hkeyp.to_bytes(emu.get_ptr_size(), 'little'))
        return 1

    @apihook('CryptDestroyKey', argc=1)
    def CryptDestroyKey(self, emu, argv, ctx={}):
        return 1

    @apihook('CryptGetKeyParam', argc=5)
    def CryptGetKeyParam(self, emu, argv, ctx={}):
        hKey, dwParam, pbData, pdwDataLen, dwFlags = argv
        ptrsz = emu.get_ptr_size()

        try:
            hkey = self.mem_cast(self.win.HCRYPTKEY(ptrsz), hKey)
            algid = int(hkey.Algid)
            key_bits = int(hkey.keylen) * 8
        except Exception:
            algid = 0x6801
            key_bits = 128

        if dwParam == 7:  # KP_ALGID
            data = algid.to_bytes(4, 'little')
        elif dwParam == 9:  # KP_KEYLEN
            data = key_bits.to_bytes(4, 'little')
        elif dwParam == 4:  # KP_MODE -- CBC
            data = (1).to_bytes(4, 'little')
        elif dwParam == 5:  # KP_MODE_BITS
            data = (8).to_bytes(4, 'little')
        elif dwParam == 8:  # KP_BLOCKLEN -- AES=128, DES=64, RC4=0
            cls = (algid >> 13) & 7
            if algid in (0x6610, 0x660E, 0x660F):  # AES variants
                blk = 128
            elif algid in (0x6601, 0x6603, 0x6609):  # DES/3DES
                blk = 64
            elif algid == 0x6801:  # RC4 (stream)
                blk = 0
            else:
                blk = 64
            data = blk.to_bytes(4, 'little')
        elif dwParam == 1:  # KP_IV -- block size in bytes
            blk_bytes = 16 if algid in (0x6610, 0x660E, 0x660F) else 8
            data = b'\\x00' * blk_bytes
        elif dwParam == 2:  # KP_SALT -- empty by default
            data = b''
        elif dwParam == 3:  # KP_PADDING -- PKCS5
            data = (1).to_bytes(4, 'little')
        elif dwParam == 6:  # KP_PERMISSIONS -- everything allowed
            data = (0x3F).to_bytes(4, 'little')
        elif dwParam == 11:  # KP_P / KP_CERTIFICATE / vendor-specific -- empty
            data = b''
        else:
            data = (0).to_bytes(4, 'little')

        if pdwDataLen:
            self.mem_write(pdwDataLen, len(data).to_bytes(4, 'little'))
        if pbData:
            self.mem_write(pbData, data)
        return 1

    @apihook('CryptSetKeyParam', argc=4)
    def CryptSetKeyParam(self, emu, argv, ctx={}):
        return 1

    @apihook('CryptExportKey', argc=6)
    def CryptExportKey(self, emu, argv, ctx={}):
        '''
        BOOL CryptExportKey(
          HCRYPTKEY hKey,
          HCRYPTKEY hExpKey,
          DWORD     dwBlobType,
          DWORD     dwFlags,
          BYTE      *pbData,
          DWORD     *pdwDataLen
        );
        '''
        hKey, hExpKey, dwBlobType, dwFlags, pbData, pdwDataLen = argv
        ptrsz = emu.get_ptr_size()
        blob_type = dwBlobType & 0xFF
        try:
            hkey = self.mem_cast(self.win.HCRYPTKEY(ptrsz), hKey)
            algid = int(hkey.Algid)
            keylen = max(1, min(int(hkey.keylen), 256))
            key = self.mem_read(hkey.keyp, keylen) if hkey.keyp else b''
        except Exception:
            algid = 0x6801
            keylen = 16
            key = bytes(range(16))

        if len(key) < keylen:
            key = (key + bytes((i & 0xFF for i in range(keylen))))[:keylen]
        header = bytes((blob_type, 2, 0, 0)) + (algid & 0xFFFFFFFF).to_bytes(4, 'little')
        if blob_type == 8:  # PLAINTEXTKEYBLOB
            blob = header + keylen.to_bytes(4, 'little') + key
        else:
            # SIMPLE/PUBLIC/PRIVATE blobs need structural bytes for callers that
            # only size/copy them. We avoid pretending to provide a valid RSA
            # key while still surfacing deterministic key material in reports.
            blob = header + key

        if pdwDataLen:
            self.mem_write(pdwDataLen, len(blob).to_bytes(4, 'little'))
        if not pbData:
            return 1
        if pdwDataLen:
            try:
                supplied = int.from_bytes(self.mem_read(pdwDataLen, 4), 'little')
            except Exception:
                supplied = len(blob)
            if supplied < len(blob):
                return 0
        self.mem_write(pbData, blob)
        return 1

"""
    text = _insert_once(text, "def CryptGenKey(", marker, handler, advapi32)
    advapi32.write_text(text, encoding="utf-8")


