def patch_kernel32_mul_div() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")

    marker = "    @apihook('lstrlen', argc=1)\n"
    handler = """    @apihook('MulDiv', argc=3)
    def MulDiv(self, emu, argv, ctx={}):
        '''
        int MulDiv(
          int nNumber,
          int nNumerator,
          int nDenominator
        );
        '''
        nNumber, nNumerator, nDenominator = argv
        if not nDenominator:
            return -1

        def signed32(v):
            v &= 0xFFFFFFFF
            return v - 0x100000000 if v & 0x80000000 else v

        num = signed32(nNumber) * signed32(nNumerator)
        den = signed32(nDenominator)
        sign = -1 if (num < 0) ^ (den < 0) else 1
        num = abs(num)
        den = abs(den)
        return sign * ((num + (den // 2)) // den)

"""
    text = _insert_once(text, "def MulDiv(", marker, handler, kernel32)
    kernel32.write_text(text, encoding="utf-8")


