def patch_kernel32_set_file_pointer_ex() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")

    marker = "    @apihook('GetFileSize', argc=2)\n"
    handler = """    @apihook('SetFilePointerEx', argc=4)
    def SetFilePointerEx(self, emu, argv, ctx={}):
        '''
        BOOL SetFilePointerEx(
          HANDLE         hFile,
          LARGE_INTEGER  liDistanceToMove,
          PLARGE_INTEGER lpNewFilePointer,
          DWORD          dwMoveMethod
        );
        '''
        hFile, liDistanceToMove, lpNewFilePointer, dwMoveMethod = argv
        rv = False

        distance = liDistanceToMove & 0xFFFFFFFFFFFFFFFF
        if distance & 0x8000000000000000:
            distance -= 0x10000000000000000

        f = self.file_get(hFile)
        if f:
            try:
                origin = dwMoveMethod if dwMoveMethod in (0, 1, 2) else 0
                f.seek(distance, origin)
                pos = f.tell()
                if lpNewFilePointer:
                    try:
                        self.mem_write(lpNewFilePointer, (pos & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'little'))
                    except Exception:
                        pass
                rv = True
                emu.set_last_error(windefs.ERROR_SUCCESS)
            except Exception:
                emu.set_last_error(windefs.ERROR_INVALID_PARAMETER)
        else:
            emu.set_last_error(windefs.ERROR_INVALID_HANDLE)

        return rv

"""
