        if not lpCPInfo:
            emu.set_last_error(windefs.ERROR_INVALID_PARAMETER)
            return False
        CodePage &= 0xFFFFFFFF
        dbcs_ranges = {
            932: [(0x81, 0x9F), (0xE0, 0xFC)],
            936: [(0x81, 0xFE)],
            949: [(0x81, 0xFE)],
            950: [(0x81, 0xFE)],
            1361: [(0x84, 0xD3), (0xD8, 0xDE), (0xE0, 0xF9)],
        }
        data = bytearray(20)
        data[0:4] = ((2 if CodePage in dbcs_ranges else 1)).to_bytes(4, 'little')
        data[4:6] = b'?\\x00'
        off = 6
        for start, end in dbcs_ranges.get(CodePage, [])[:5]:
            data[off] = start
            data[off + 1] = end
            off += 2
        self.mem_write(lpCPInfo, bytes(data))
