def patch_kernel32_multibyte_conversion_guards() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")
    if "Speakeasy overlay: guarded WideCharToMultiByte" in text:
        return

    def replace_hook(src: str, hook: str, block: str) -> str:
        marker = f"    @apihook('{hook}',"
        start = src.find(marker)
        if start < 0:
            raise RuntimeError(f"{hook} patch anchor not found in {kernel32}")
        next_start = src.find("\n    @apihook(", start + len(marker))
        if next_start < 0:
            raise RuntimeError(f"{hook} patch end not found in {kernel32}")
        return src[:start] + block + src[next_start + 1:]

    wide_to_multi = """    @apihook('WideCharToMultiByte', argc=8)
    def WideCharToMultiByte(self, emu, argv, ctx={}):
        '''
        int WideCharToMultiByte(
          UINT CodePage, DWORD dwFlags, LPCWCH lpWideCharStr, int cchWideChar,
          LPSTR lpMultiByteStr, int cbMultiByte, LPCCH lpDefaultChar,
          LPBOOL lpUsedDefaultChar
        );
        '''
        # Speakeasy overlay: guarded WideCharToMultiByte.
        CodePage, dwFlags, lpWideCharStr, cchWideChar, lpMultiByteStr, cbMultiByte, lpDefaultChar, lpUsedDefaultChar = argv
        try:
            cch = cchWideChar & 0xFFFFFFFF
            if not lpWideCharStr:
                emu.set_last_error(windefs.ERROR_INVALID_PARAMETER)
                return 0
            if cch == 0xFFFFFFFF:
                text = self.read_mem_string(lpWideCharStr, 2)
                include_nul = True
            else:
                raw = self.mem_read(lpWideCharStr, min(cch, 0x100000) * 2)
                text = raw.decode('utf-16le', errors='ignore').rstrip('\\x00')
                include_nul = False
        except Exception:
            text = ''
            include_nul = False
        data = text.encode('utf-8', errors='ignore') + (b'\\x00' if include_nul else b'')
        argv[2] = text
        if lpUsedDefaultChar:
            try:
                self.mem_write(lpUsedDefaultChar, (0).to_bytes(4, 'little'))
            except Exception:
                pass
        cb = cbMultiByte & 0xFFFFFFFF
        if not lpMultiByteStr or cb == 0:
            emu.set_last_error(windefs.ERROR_SUCCESS)
            return len(data)
        try:
            self.mem_write(lpMultiByteStr, data[:cb])
            emu.set_last_error(windefs.ERROR_SUCCESS)
            return min(len(data), cb)
        except Exception:
            emu.set_last_error(windefs.ERROR_INVALID_PARAMETER)
            return 0

"""
    multi_to_wide = """    @apihook('MultiByteToWideChar', argc=6)
    def MultiByteToWideChar(self, emu, argv, ctx={}):
        '''
        int MultiByteToWideChar(
          UINT CodePage, DWORD dwFlags, LPCCH lpMultiByteStr, int cbMultiByte,
          LPWSTR lpWideCharStr, int cchWideChar
        );
        '''
        CodePage, dwFlags, lpMultiByteStr, cbMultiByte, lpWideCharStr, cchWideChar = argv
        try:
            cb = cbMultiByte & 0xFFFFFFFF
            if not lpMultiByteStr:
                emu.set_last_error(windefs.ERROR_INVALID_PARAMETER)
                return 0
            if cb == 0xFFFFFFFF:
                text = self.read_mem_string(lpMultiByteStr, 1)
                include_nul = True
            else:
                raw = self.mem_read(lpMultiByteStr, min(cb, 0x100000))
                text = raw.decode('utf-8', errors='ignore').rstrip('\\x00')
                include_nul = False
        except Exception:
            text = ''
            include_nul = False
        out = text.encode('utf-16le', errors='ignore') + (b'\\x00\\x00' if include_nul else b'')
        required_chars = len(out) // 2
        argv[2] = text
        cch = cchWideChar & 0xFFFFFFFF
        if not lpWideCharStr or cch == 0:
            emu.set_last_error(windefs.ERROR_SUCCESS)
            return required_chars
        try:
            self.mem_write(lpWideCharStr, out[:cch * 2])
            emu.set_last_error(windefs.ERROR_SUCCESS)
            return min(required_chars, cch)
        except Exception:
            emu.set_last_error(windefs.ERROR_INVALID_PARAMETER)
            return 0

"""
    text = replace_hook(text, "WideCharToMultiByte", wide_to_multi)
    text = replace_hook(text, "MultiByteToWideChar", multi_to_wide)
    kernel32.write_text(text, encoding="utf-8")


