def patch_kernel32_heap_realloc_guard() -> None:
    kernel32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "kernel32.py"
    text = kernel32.read_text(encoding="utf-8")
    if "Speakeasy overlay: guarded HeapReAlloc copy length" in text:
        return

    old = """    @apihook('HeapReAlloc', argc=4)
    def HeapReAlloc(self, emu, argv, ctx={}):
        '''
        DECLSPEC_ALLOCATOR LPVOID HeapReAlloc(
          HANDLE                 hHeap,
          DWORD                  dwFlags,
          _Frees_ptr_opt_ LPVOID lpMem,
          SIZE_T                 dwBytes
        );
        '''

        hHeap, dwFlags, lpMem, dwBytes = argv

        tag_prefix = 'api.heap'
        new_buf = 0

        if hHeap and lpMem and dwBytes:
            mm = emu.get_address_map(lpMem)
            if mm and mm.get_tag().startswith(tag_prefix):
                # Copy the existing data
                data = self.mem_read(lpMem, mm.get_size())
                new_buf = self.heap_alloc(dwBytes, heap='HeapReAlloc')
                self.mem_write(new_buf, data)

        return new_buf

"""
    new = """    @apihook('HeapReAlloc', argc=4)
    def HeapReAlloc(self, emu, argv, ctx={}):
        '''
        DECLSPEC_ALLOCATOR LPVOID HeapReAlloc(
          HANDLE                 hHeap,
          DWORD                  dwFlags,
          _Frees_ptr_opt_ LPVOID lpMem,
          SIZE_T                 dwBytes
        );
        '''

        hHeap, dwFlags, lpMem, dwBytes = argv
        size = max(1, dwBytes & 0xFFFFFFFF)
        if not hHeap or not size:
            return 0

        # Speakeasy overlay: guarded HeapReAlloc copy length.
        new_buf = self.heap_alloc(size, heap='HeapReAlloc')
        if lpMem:
            try:
                mm = emu.get_address_map(lpMem)
                old_size = mm.get_size() if mm else 0
                copy_size = min(size, old_size, 0x100000)
                if copy_size:
                    self.mem_write(new_buf, self.mem_read(lpMem, copy_size))
            except Exception:
                pass
        return new_buf

"""
    if old not in text:
        raise RuntimeError(f"HeapReAlloc patch anchor not found in {kernel32}")
    kernel32.write_text(text.replace(old, new, 1), encoding="utf-8")


