    def _sx_mixed_case_string_type_flags(self, ch):
        flags = 0
        if ch.isupper():
            flags |= 0x0001  # C1_UPPER
        if ch.islower():
            flags |= 0x0002  # C1_LOWER
        if ch.isdigit():
            flags |= 0x0004  # C1_DIGIT
        if ch.isspace():
            flags |= 0x0008  # C1_SPACE
        if not ch.isalnum() and not ch.isspace():
            flags |= 0x0010  # C1_PUNCT
        if ord(ch) < 0x20:
            flags |= 0x0020  # C1_CNTRL
        if ch in (' ', '\\t'):
            flags |= 0x0040  # C1_BLANK
        if ch in '0123456789abcdefABCDEF':
            flags |= 0x0080  # C1_XDIGIT
        if ch.isalpha():
            flags |= 0x0100  # C1_ALPHA
        return flags or 0x0010

    def _sx_mixed_case_get_string_type(self, lpSrcStr, cchSrc, lpCharType, cw):
        if not lpSrcStr:
            return 0
        try:
            cch = cchSrc & 0xFFFFFFFF
            if cch == 0xFFFFFFFF:
                text = self.read_mem_string(lpSrcStr, cw)
            else:
                cch = min(cch, 0x1000)
                raw = self.mem_read(lpSrcStr, cch * cw)
                enc = 'utf-16le' if cw == 2 else 'utf-8'
                text = raw.decode(enc, errors='ignore').split('\\x00', 1)[0]
        except Exception:
            text = ''
        if lpCharType:
            for idx, ch in enumerate(text[:0x1000]):
                flags = self._sx_mixed_case_string_type_flags(ch)
                self.mem_write(lpCharType + (idx * 2), flags.to_bytes(2, 'little'))
        return 1

