        if not ptr:
            return
        try:
            raw = bytearray(172)
            # Windows Bias is minutes added to local time to obtain UTC.
            # A UTC+05 workstation therefore uses -300.
            raw[0:4] = (0xFFFFFED4).to_bytes(4, 'little')
            standard = 'West Asia Standard Time'.encode('utf-16le')[:64]
            daylight = 'West Asia Daylight Time'.encode('utf-16le')[:64]
            raw[4:4 + len(standard)] = standard
            raw[88:88 + len(daylight)] = daylight
            raw[84:88] = (0).to_bytes(4, 'little')
            raw[168:172] = (0).to_bytes(4, 'little')
            self.mem_write(ptr, bytes(raw))
        except Exception:
            pass

