def patch_ntdll_version_helpers() -> None:
    ntdll = _speakeasy_root() / "winenv" / "api" / "usermode" / "ntdll.py"
    text = ntdll.read_text(encoding="utf-8")

    marker = "    @apihook('RtlGetNtVersionNumbers', argc=3)\n"
    handler = """    def _sx_rtl_version(self):
        return {
            'major': 10,
            'minor': 0,
            'build': 22631,
            'platform': 2,
            'service_pack_major': 0,
            'service_pack_minor': 0,
            'suite_mask': 0x100,
            'product_type': 1,
        }

    def _sx_write_osversioninfoexw(self, emu, ptr):
        if not ptr:
            return
        version = self._sx_rtl_version()
        try:
            requested_size = int.from_bytes(self.mem_read(ptr, 4), 'little')
        except Exception:
            requested_size = 284
        size = requested_size if 0 < requested_size <= 284 else 284
        data = bytearray(b'\\x00' * 284)
        data[0:4] = size.to_bytes(4, 'little')
        data[4:8] = version['major'].to_bytes(4, 'little')
        data[8:12] = version['minor'].to_bytes(4, 'little')
        data[12:16] = version['build'].to_bytes(4, 'little')
        data[16:20] = version['platform'].to_bytes(4, 'little')
        data[276:278] = version['service_pack_major'].to_bytes(2, 'little')
        data[278:280] = version['service_pack_minor'].to_bytes(2, 'little')
        data[280:282] = version['suite_mask'].to_bytes(2, 'little')
        data[282] = version['product_type'] & 0xFF
        self.mem_write(ptr, bytes(data[:size]))

    @apihook('VerSetConditionMask', argc=3)
    def VerSetConditionMask(self, emu, argv, ctx={}):
        ConditionMask, TypeMask, Condition = argv
        mask = ConditionMask & 0xFFFFFFFFFFFFFFFF
        type_mask = TypeMask & 0xFFFFFFFF
        condition = Condition & 0x7
        bit = 1
        shift = 0
        while bit <= 0x80:
            if type_mask & bit:
                mask &= ~(0x7 << shift)
                mask |= condition << shift
            bit <<= 1
            shift += 3
        return mask

    @apihook('RtlGetVersion', argc=1)
    def RtlGetVersion(self, emu, argv, ctx={}):
        '''
        NTSTATUS RtlGetVersion(PRTL_OSVERSIONINFOW lpVersionInformation);
        '''
        lpVersionInformation, = argv
        self._sx_write_osversioninfoexw(emu, lpVersionInformation)
        return ddk.STATUS_SUCCESS

    @apihook('RtlVerifyVersionInfo', argc=3)
    def RtlVerifyVersionInfo(self, emu, argv, ctx={}):
        '''
        NTSTATUS RtlVerifyVersionInfo(
          PRTL_OSVERSIONINFOEXW VersionInfo,
          ULONG                 TypeMask,
          ULONGLONG             ConditionMask
        );
        '''
        VersionInfo, TypeMask, ConditionMask = argv
        version = self._sx_rtl_version()

        def read_int(offset, size):
            try:
                return int.from_bytes(self.mem_read(VersionInfo + offset, size), 'little')
            except Exception:
                return 0

        def condition_for(type_bit):
            shift = 0
            bit = type_bit
            while bit > 1:
                bit >>= 1
                shift += 3
            return (ConditionMask >> shift) & 0x7

        def compare(current, requested, condition):
            # 0 means caller did not provide a condition for that field. Be
            # permissive: many samples misuse version helpers for probing only.
            if condition == 0:
                return True
            if condition == 1:
                return current == requested
            if condition == 2:
                return current > requested
            if condition == 3:
                return current >= requested
            if condition == 4:
                return current < requested
            if condition == 5:
                return current <= requested
            if condition == 6:
                return (current & requested) == requested
            if condition == 7:
                return bool(current & requested)
            return True

        checks = (
            (0x00000001, read_int(8, 4), version['minor']),
            (0x00000002, read_int(4, 4), version['major']),
            (0x00000004, read_int(12, 4), version['build']),
            (0x00000008, read_int(16, 4), version['platform']),
            (0x00000010, read_int(278, 2), version['service_pack_minor']),
            (0x00000020, read_int(276, 2), version['service_pack_major']),
            (0x00000040, read_int(280, 2), version['suite_mask']),
            (0x00000080, read_int(282, 1), version['product_type']),
        )
        for type_bit, requested, current in checks:
            if TypeMask & type_bit and not compare(current, requested, condition_for(type_bit)):
                return 0xC0000059  # STATUS_REVISION_MISMATCH
        return ddk.STATUS_SUCCESS

"""
    text = _insert_once(text, "def RtlGetVersion(", marker, handler, ntdll)
