def patch_ntdll_time_conversion_helpers() -> None:
    ntdll = _speakeasy_root() / "winenv" / "api" / "usermode" / "ntdll.py"
    text = ntdll.read_text(encoding="utf-8")

    marker = "    @apihook('NtDelayExecution', argc=2)\n"
    handler = """    def _sx_filetime_to_unix_seconds(self, ptr):
        if not ptr:
            return 1576300968
        try:
            ft = int.from_bytes(self.mem_read(ptr, 8), 'little', signed=False)
            if ft >= 116444736000000000:
                return (ft - 116444736000000000) // 10000000
        except Exception:
            pass
        return 1576300968

    def _sx_unix_seconds_to_filetime(self, seconds):
        return (int(seconds or 0) * 10000000) + 116444736000000000

    @apihook('RtlTimeToSecondsSince1970', argc=2)
    def RtlTimeToSecondsSince1970(self, emu, argv, ctx={}):
        Time, ElapsedSeconds = argv
        seconds = self._sx_filetime_to_unix_seconds(Time)
        if ElapsedSeconds:
            try:
                self.mem_write(ElapsedSeconds, (seconds & 0xFFFFFFFF).to_bytes(4, 'little'))
            except Exception:
                pass
        return 1

    @apihook('RtlSecondsSince1970ToTime', argc=2)
    def RtlSecondsSince1970ToTime(self, emu, argv, ctx={}):
        ElapsedSeconds, Time = argv
        if Time:
            try:
                ft = self._sx_unix_seconds_to_filetime(ElapsedSeconds & 0xFFFFFFFF)
                self.mem_write(Time, (ft & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'little'))
            except Exception:
                pass
        return None

    @apihook('RtlTimeToSecondsSince1980', argc=2)
    def RtlTimeToSecondsSince1980(self, emu, argv, ctx={}):
        Time, ElapsedSeconds = argv
        seconds = max(0, self._sx_filetime_to_unix_seconds(Time) - 315532800)
        if ElapsedSeconds:
            try:
                self.mem_write(ElapsedSeconds, (seconds & 0xFFFFFFFF).to_bytes(4, 'little'))
            except Exception:
                pass
        return 1

    @apihook('RtlSecondsSince1980ToTime', argc=2)
    def RtlSecondsSince1980ToTime(self, emu, argv, ctx={}):
        ElapsedSeconds, Time = argv
        return self.RtlSecondsSince1970ToTime(emu, [(ElapsedSeconds & 0xFFFFFFFF) + 315532800, Time], ctx)

    @apihook('RtlSystemTimeToLocalTime', argc=2)
    def RtlSystemTimeToLocalTime(self, emu, argv, ctx={}):
        SystemTime, LocalTime = argv
        if SystemTime and LocalTime:
            try:
                # UTC+05 workstation: local FILETIME is system time + 5h.
                ft = int.from_bytes(self.mem_read(SystemTime, 8), 'little') + (5 * 60 * 60 * 10000000)
                self.mem_write(LocalTime, (ft & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'little'))
            except Exception:
                pass
        return ddk.STATUS_SUCCESS

    @apihook('RtlLocalTimeToSystemTime', argc=2)
    def RtlLocalTimeToSystemTime(self, emu, argv, ctx={}):
        LocalTime, SystemTime = argv
        if LocalTime and SystemTime:
            try:
                ft = int.from_bytes(self.mem_read(LocalTime, 8), 'little') - (5 * 60 * 60 * 10000000)
                self.mem_write(SystemTime, (ft & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'little'))
            except Exception:
                pass
        return ddk.STATUS_SUCCESS

    @apihook('RtlTimeToTimeFields', argc=2)
    def RtlTimeToTimeFields(self, emu, argv, ctx={}):
        Time, TimeFields = argv
        if TimeFields:
            # TIME_FIELDS: Year, Month, Day, Hour, Minute, Second,
            # Milliseconds, Weekday (USHORT each). Deterministic local profile.
            vals = (2019, 12, 14, 5, 22, 48, 0, 6)
            try:
                self.mem_write(TimeFields, b''.join((v & 0xFFFF).to_bytes(2, 'little') for v in vals))
            except Exception:
                pass
        return None

"""
    text = _insert_once(text, "def RtlTimeToSecondsSince1970(", marker, handler, ntdll)
    ntdll.write_text(text, encoding="utf-8")


