    def _sx_nt_path(self, path):
        path = path or ''
        if path.startswith('\\\\??\\\\') or path.startswith('\\\\Device\\\\'):
            return path
        if path.startswith('\\\\\\\\'):
            return '\\\\??\\\\UNC\\\\' + path.lstrip('\\\\')
        return '\\\\??\\\\' + path

    def _sx_read_unicode_string(self, emu, unicode_string):
        if not unicode_string:
            return ''
        try:
            us = ntos.UNICODE_STRING(emu.get_ptr_size())
            self.mem_cast(us, unicode_string)
            if not us.Buffer or not us.Length:
                return ''
            raw = self.mem_read(us.Buffer, min(us.Length, 0x2000))
            return raw.decode('utf-16le', errors='ignore').rstrip('\\x00')
        except Exception:
            return ''

