def patch_ntoskrnl_zw_query_system_information_fallback() -> None:
    ntoskrnl = _speakeasy_root() / "winenv" / "api" / "kernelmode" / "ntoskrnl.py"
    text = ntoskrnl.read_text(encoding="utf-8")

    old = """        else:
            raise ApiEmuError('Unsupported information class: 0x%x'
                              % (sysclass))

        if retlen:
            self.mem_write(retlen, size.to_bytes(4, 'little'))
"""
    new = """        else:
            # Keep kernel-mode probes moving for common anti-analysis and runtime
            # checks. Native Windows returns structured buffers for many classes;
            # here we provide conservative workstation-shaped zeroed buffers
            # instead of aborting the emulation path.
            nts = ddk.STATUS_SUCCESS
            size = min(syslen if syslen else 0x40, 0x1000)
            data = bytearray(b'\\x00' * size)

            def put32(off, value):
                if off + 4 <= len(data):
                    data[off:off + 4] = (value & 0xFFFFFFFF).to_bytes(4, 'little')

            def put64(off, value):
                if off + 8 <= len(data):
                    data[off:off + 8] = (value & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'little')

            if sysclass == 0:  # SystemBasicInformation
                size = max(size, 0x2C if emu.get_ptr_size() == 4 else 0x40)
                data = bytearray(b'\\x00' * min(size, 0x1000))
                put32(4, 10000)   # TimerResolution
                put32(8, 4096)    # PageSize
                put32(24, 4)      # NumberOfProcessors
            elif sysclass == 2:  # SystemPerformanceInformation
                size = max(size, 0x138)
                data = bytearray(b'\\x00' * min(size, 0x1000))
                put64(0, 6 * 1024 * 1024 * 1024)
                put64(8, 2 * 1024 * 1024 * 1024)
            elif sysclass in (0x67, 0x9f):  # Hypervisor-related checks
                size = max(size, 0x10)
                data = bytearray(b'\\x00' * min(size, 0x1000))

            if sysinfo and syslen:
                self.mem_write(sysinfo, bytes(data[:syslen]))

        if retlen:
            self.mem_write(retlen, size.to_bytes(4, 'little'))
"""
    if old in text:
        text = text.replace(old, new, 1)
    elif "Unsupported information class" in text and "workstation-shaped zeroed buffers" not in text:
        raise RuntimeError(f"ZwQuerySystemInformation patch anchor drifted in {ntoskrnl}")
    ntoskrnl.write_text(text, encoding="utf-8")


