        FirmwareTableProviderSignature, pFirmwareTableBuffer, BufferSize = argv
        tables = b'FACPDSDT'
        if pFirmwareTableBuffer and BufferSize:
            try:
                self.mem_write(pFirmwareTableBuffer, tables[:BufferSize & 0xFFFFFFFF])
            except Exception:
                pass
        return len(tables)

