    def _sx_write_slist_head(self, emu, head, first=0, depth=0):
        if not head:
            return
        try:
            ptr_size = emu.get_ptr_size()
            if ptr_size == 8:
                # Enough for callers that inspect first pointer/depth loosely.
                self.mem_write(head, first.to_bytes(8, 'little') + (depth & 0xFFFF).to_bytes(2, 'little') + b'\\x00' * 6)
            else:
                self.mem_write(head, first.to_bytes(4, 'little') + (depth & 0xFFFF).to_bytes(2, 'little') + b'\\x00\\x00')
        except Exception:
            pass

