    def _sx_map_view(self, emu, mapping, desired_access, offset_high, offset_low, bytes_to_map, base=0):
        size = bytes_to_map & 0xFFFFFFFF
        if not size:
            size = 0x10000
        size = max(0x1000, min(size, 0x1000000))
        try:
            ptr = self.mem_alloc(size, tag='api.kernel32.map_view')
            self.mem_write(ptr, b'\\x00' * min(size, 0x10000))
        except Exception:
            ptr = base or 0x74000000
        views = getattr(self, '_sx_mapped_views', {})
        views[ptr] = {'mapping': mapping, 'size': size, 'offset': ((offset_high & 0xFFFFFFFF) << 32) | (offset_low & 0xFFFFFFFF)}
        self._sx_mapped_views = views
        return ptr

