        total = 8 * 1024 * 1024 * 1024
        avail = 6 * 1024 * 1024 * 1024
        data = bytearray(64)
        data[0:4] = (64).to_bytes(4, 'little')
        data[4:8] = (25).to_bytes(4, 'little')
        values = [total, avail, total * 2, avail * 2, 0x7FFFFFFF0000, 0x7FFFF0000000, 0]
        off = 8
