    def _sx_get_file_attributes_ex(self, emu, argv, width):
        lpFileName, fInfoLevelId, lpFileInformation = argv
        path = ''
        if lpFileName:
            try:
                path = self.read_mem_string(lpFileName, width)
                argv[0] = path
            except Exception:
                path = ''
        attrs = None
        try:
            if path and self.does_file_exist(path):
                attrs = 0x80
        except Exception:
            attrs = None
        if attrs is None and hasattr(self, '_sx_synthetic_path_attrs'):
            attrs = self._sx_synthetic_path_attrs(path)
        if attrs is None:
            emu.set_last_error(windefs.ERROR_FILE_NOT_FOUND)
            return 0
        if lpFileInformation:
            # WIN32_FILE_ATTRIBUTE_DATA: attrs + 3 FILETIME fields + size high/low.
            ft = 133485408000000000
            size = 4096 if attrs != 0x10 else 0
            data = bytearray(36)
            data[0:4] = (attrs & 0xFFFFFFFF).to_bytes(4, 'little')
            data[4:12] = ft.to_bytes(8, 'little')
            data[12:20] = (ft + 600000000).to_bytes(8, 'little')
            data[20:28] = (ft + 1200000000).to_bytes(8, 'little')
            data[28:32] = (0).to_bytes(4, 'little')
            data[32:36] = (size & 0xFFFFFFFF).to_bytes(4, 'little')
            try:
                self.mem_write(lpFileInformation, bytes(data))
            except Exception:
                pass
        emu.set_last_error(windefs.ERROR_SUCCESS)
        return 1

