    @apihook('GetTempFileNameW', argc=4)
    def zz_GetTempFileNameW(self, emu, argv, ctx={}):
        lpPathName, lpPrefixString, uUnique, lpTempFileName = argv
        path = 'C:\\\\Users\\\\john\\\\AppData\\\\Local\\\\Temp'
        prefix = 'vr'
        try:
            if lpPathName:
                path = self.read_mem_string(lpPathName, 2) or path
            if lpPrefixString:
                prefix = self.read_mem_string(lpPrefixString, 2) or prefix
        except Exception:
            pass
        uid = uUnique or ((getattr(self, '_sx_tmpfile_uid', 0x1000) + 1) & 0xFFFF)
        if not uUnique:
            self._sx_tmpfile_uid = uid
        value = path.rstrip('\\\\/') + '\\\\' + prefix[:3] + '%04X.tmp' % uid
        if lpTempFileName:
            self.write_mem_string(value, lpTempFileName, 2)
        argv[0] = path
        argv[1] = prefix
        return uid

