    def _sx_private_profile_section_names(self, argv, width):
        lpReturnedString, nSize, lpFileName = argv
        if lpFileName:
            try:
                argv[2] = self.read_mem_string(lpFileName, width)
            except Exception:
                pass
        names = 'General\\x00Settings\\x00\\x00'
        raw = names.encode('utf-16le') if width == 2 else names.encode('utf-8')
        limit = (nSize & 0xFFFFFFFF) * width
        if lpReturnedString and limit:
            try:
                self.mem_write(lpReturnedString, raw[:limit])
            except Exception:
                pass
        return max(0, min(len(raw) // width, nSize & 0xFFFFFFFF) - 2)

