    def _sx_private_profile_struct(self, emu, argv, width):
        lpAppName, lpKeyName, lpStruct, uSizeStruct, lpFileName = argv
        for idx, ptr in ((0, lpAppName), (1, lpKeyName), (4, lpFileName)):
            if ptr:
                try:
                    argv[idx] = self.read_mem_string(ptr, width)
                except Exception:
                    pass
        # No backing INI corpus is available in the emulator. Windows returns
        # FALSE when the section/key is absent; zeroing the caller's buffer makes
        # probes deterministic without fabricating malware config material.
        if lpStruct and uSizeStruct:
            try:
                self.mem_write(lpStruct, b'\\x00' * min(uSizeStruct & 0xFFFFFFFF, 0x10000))
            except Exception:
                pass
        emu.set_last_error(2)
        return 0

