def patch_ws2_inet_ntoa_cached_buffer() -> None:
    ws2 = _speakeasy_root() / "winenv" / "api" / "usermode" / "ws2_32.py"
    text = ws2.read_text(encoding="utf-8")
    if "Speakeasy overlay: return cached inet_ntoa buffers" in text:
        return

    old = """    @apihook('inet_ntoa', argc=1, ordinal=12)
    def inet_ntoa(self, emu, argv, ctx={}):
        \"\"\"
        char FAR* inet_ntoa(struct in_addr in);
        \"\"\"
        in_addr, = argv

        raddr = inet_ntoa(in_addr.to_bytes(4, 'little'))
        rv = self.addr_bufs.get(raddr)
        if not rv:
            buf = self.mem_alloc(len(raddr), tag='api.ws2_32.inet_ntoa.%s' % (raddr))
            self.mem_write(buf, raddr.encode('utf-8'))
            self.addr_bufs.update({raddr: buf})
        return buf

"""
    new = """    @apihook('inet_ntoa', argc=1, ordinal=12)
    def inet_ntoa(self, emu, argv, ctx={}):
        \"\"\"
        char FAR* inet_ntoa(struct in_addr in);
        \"\"\"
        in_addr, = argv

        raddr = inet_ntoa((in_addr & 0xFFFFFFFF).to_bytes(4, 'little'))
        rv = self.addr_bufs.get(raddr)
        if not rv:
            # Speakeasy overlay: return cached inet_ntoa buffers.
            # Upstream allocated a new buffer, cached it, then returned the local
            # variable even when an address already existed in addr_bufs.
            rv = self.mem_alloc(len(raddr) + 1, tag='api.ws2_32.inet_ntoa.%s' % (raddr))
            self.mem_write(rv, raddr.encode('utf-8') + b'\\x00')
            self.addr_bufs.update({raddr: rv})
        argv[0] = raddr
        return rv

"""
    if old not in text:
        raise RuntimeError(f"inet_ntoa patch anchor not found in {ws2}")
    ws2.write_text(text.replace(old, new, 1), encoding="utf-8")


