def patch_ws2_event_helpers() -> None:
    ws2 = _speakeasy_root() / "winenv" / "api" / "usermode" / "ws2_32.py"
    text = ws2.read_text(encoding="utf-8")

    marker = "    @apihook('WSASetLastError', argc=1, ordinal=112)\n"
    handler = """    def _sx_wsa_events(self):
        events = getattr(self, '_sx_wsa_event_state', None)
        if events is None:
            events = {}
            self._sx_wsa_event_state = events
        return events

    def _sx_wsa_socket_events(self):
        events = getattr(self, '_sx_wsa_socket_event_state', None)
        if events is None:
            events = {}
            self._sx_wsa_socket_event_state = events
        return events

    def _sx_next_wsa_event_handle(self):
        handle = getattr(self, '_sx_next_wsa_event_value', 0x76000000) + 4
        self._sx_next_wsa_event_value = handle
        return handle

    def _sx_wsa_event_mask(self, sock, requested=0):
        requested &= 0xFFFFFFFF
        if requested:
            # Prefer readiness bits that malware usually waits for after
            # nonblocking connect/send setup. Keep only requested bits so branch
            # logic sees a plausible subset rather than all events.
            ready = 0x10 | 0x02 | 0x01  # FD_CONNECT | FD_WRITE | FD_READ
            return requested & ready or requested
        return 0x10 | 0x02

    @apihook('WSACreateEvent', argc=0)
    def WSACreateEvent(self, emu, argv, ctx={}):
        handle = self._sx_next_wsa_event_handle()
        self._sx_wsa_events()[handle] = {
            'manual_reset': True,
            'signaled': True,
            'socket': 0,
            'mask': 0,
        }
        self.last_error = windefs.ERROR_SUCCESS
        return handle

    @apihook('WSACloseEvent', argc=1)
    def WSACloseEvent(self, emu, argv, ctx={}):
        hEvent, = argv
        self._sx_wsa_events().pop(hEvent, None)
        self.last_error = windefs.ERROR_SUCCESS
        return 1

    @apihook('WSAResetEvent', argc=1)
    def WSAResetEvent(self, emu, argv, ctx={}):
        hEvent, = argv
        evt = self._sx_wsa_events().setdefault(hEvent, {})
        evt['signaled'] = False
        self.last_error = windefs.ERROR_SUCCESS
        return 1

    @apihook('WSASetEvent', argc=1)
    def WSASetEvent(self, emu, argv, ctx={}):
        hEvent, = argv
        evt = self._sx_wsa_events().setdefault(hEvent, {})
        evt['signaled'] = True
        self.last_error = windefs.ERROR_SUCCESS
        return 1

    @apihook('WSAEventSelect', argc=3)
    def WSAEventSelect(self, emu, argv, ctx={}):
        s, hEventObject, lNetworkEvents = argv
        mask = lNetworkEvents & 0xFFFFFFFF
        evt = self._sx_wsa_events().setdefault(hEventObject, {})
        evt.update({
            'signaled': True,
            'socket': s,
            'mask': mask,
        })
        self._sx_wsa_socket_events()[s] = hEventObject
        self.last_error = windefs.ERROR_SUCCESS
        return 0

    @apihook('WSAAsyncSelect', argc=4)
    def WSAAsyncSelect(self, emu, argv, ctx={}):
        s, hWnd, wMsg, lEvent = argv
        self._sx_wsa_socket_events()[s] = {
            'hwnd': hWnd,
            'message': wMsg,
            'mask': lEvent & 0xFFFFFFFF,
        }
        self.last_error = windefs.ERROR_SUCCESS
        return 0

    @apihook('WSAEnumNetworkEvents', argc=3)
    def WSAEnumNetworkEvents(self, emu, argv, ctx={}):
        s, hEventObject, lpNetworkEvents = argv
        evt = self._sx_wsa_events().get(hEventObject, {})
        requested = int(evt.get('mask', 0) or 0)
        mask = self._sx_wsa_event_mask(s, requested)
        if lpNetworkEvents:
            # WSANETWORKEVENTS: long lNetworkEvents; int iErrorCode[FD_MAX_EVENTS].
            # Error codes are zero for every signaled event in this offline model.
            data = (mask & 0xFFFFFFFF).to_bytes(4, 'little') + (b'\\x00' * (10 * 4))
            try:
                self.mem_write(lpNetworkEvents, data)
            except Exception:
                pass
        if hEventObject in self._sx_wsa_events():
            self._sx_wsa_events()[hEventObject]['signaled'] = False
        self.last_error = windefs.ERROR_SUCCESS
        return 0

    @apihook('WSAWaitForMultipleEvents', argc=5)
    def WSAWaitForMultipleEvents(self, emu, argv, ctx={}):
        cEvents, lphEvents, fWaitAll, dwTimeout, fAlertable = argv
        cEvents &= 0xFFFFFFFF
        if not cEvents or not lphEvents:
            self.last_error = 10022  # WSAEINVAL
            return 0xFFFFFFFF
        ptr_size = emu.get_ptr_size()
        events = []
        for i in range(min(cEvents, 64)):
            try:
                events.append(int.from_bytes(self.mem_read(lphEvents + (i * ptr_size), ptr_size), 'little'))
            except Exception:
                break
        # Return WSA_WAIT_EVENT_0 + index. We model network readiness as already
        # available so malware reaches recv/send/error-handling logic offline.
        for i, event in enumerate(events or [0]):
            if event in self._sx_wsa_events() or i == 0:
                self.last_error = windefs.ERROR_SUCCESS
                return i
        if (dwTimeout & 0xFFFFFFFF) == 0:
            return 258  # WSA_WAIT_TIMEOUT / WAIT_TIMEOUT
        self.last_error = windefs.ERROR_SUCCESS
        return 0

    @apihook('WSAGetOverlappedResult', argc=5)
    def WSAGetOverlappedResult(self, emu, argv, ctx={}):
        s, lpOverlapped, lpcbTransfer, fWait, lpdwFlags = argv
        if lpcbTransfer:
            try:
                self.mem_write(lpcbTransfer, (0).to_bytes(4, 'little'))
            except Exception:
                pass
        if lpdwFlags:
            try:
                self.mem_write(lpdwFlags, (0).to_bytes(4, 'little'))
            except Exception:
                pass
        self.last_error = windefs.ERROR_SUCCESS
        return 1

    @apihook('WSAGetLastError', argc=0, ordinal=111)
    def WSAGetLastError(self, emu, argv, ctx={}):
        return getattr(self, 'last_error', 0)

"""
    text = _insert_once(text, "def WSACreateEvent(", marker, handler, ws2)
    ws2.write_text(text, encoding="utf-8")


