        data[12:16] = (0x10000000).to_bytes(4, 'little') # dwMaxTxQueue
        data[16:20] = (0x10000000).to_bytes(4, 'little') # dwMaxRxQueue
        data[20:24] = (115200).to_bytes(4, 'little')     # dwMaxBaud
        data[44:48] = (6).to_bytes(4, 'little')          # dwProvSubType: PST_RS232
