def patch_user32_vk_key_scan() -> None:
    user32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "user32.py"
    text = user32.read_text(encoding="utf-8")

    marker = "    @apihook('GetKeyboardLayoutList', argc=2)\n"
    handler = """    @apihook('VkKeyScan', argc=1)
    def VkKeyScan(self, emu, argv, ctx={}):
        '''
        SHORT VkKeyScan(
          TCHAR ch
        );
        '''
        ch, = argv
        ch &= 0xFFFF

        if 0x61 <= ch <= 0x7A:
            return ch - 0x20
        if 0x41 <= ch <= 0x5A:
            return ch | 0x0100
        if 0x30 <= ch <= 0x39:
            return ch
        table = {
            0x08: 0x08,
            0x09: 0x09,
            0x0D: 0x0D,
            0x1B: 0x1B,
            0x20: 0x20,
            ord('.'): ord('.'),
            ord(','): ord(','),
            ord('-'): ord('-'),
            ord('_'): ord('-') | 0x0100,
        }
        return table.get(ch, 0xFFFF)

"""
