def patch_user32_system_metrics_realistic() -> None:
    user32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "user32.py"
    text = user32.read_text(encoding="utf-8")

    old = """    @apihook('GetSystemMetrics', argc=1)
    def GetSystemMetrics(self, emu, argv, ctx={}):
        \"\"\"
        int GetSystemMetrics(
          int nIndex
        );
        \"\"\"

        nIndex, = argv

        rv = 1
        return rv

"""
    new = """    @apihook('GetSystemMetrics', argc=1)
    def GetSystemMetrics(self, emu, argv, ctx={}):
        \"\"\"
        int GetSystemMetrics(
          int nIndex
        );
        \"\"\"

        nIndex, = argv
        nIndex &= 0xFFFFFFFF
        metrics = {
            0: 1920,   # SM_CXSCREEN
            1: 1080,   # SM_CYSCREEN
            2: 17,     # SM_CXVSCROLL
            3: 17,     # SM_CYHSCROLL
            4: 23,     # SM_CYCAPTION
            5: 1,      # SM_CXBORDER
            6: 1,      # SM_CYBORDER
            7: 4,      # SM_CXDLGFRAME
            8: 4,      # SM_CYDLGFRAME
            9: 20,     # SM_CYVTHUMB
            10: 20,    # SM_CXHTHUMB
            11: 32,    # SM_CXICON
            12: 32,    # SM_CYICON
            13: 32,    # SM_CXCURSOR
            14: 32,    # SM_CYCURSOR
            15: 20,    # SM_CYMENU
            16: 1920,  # SM_CXFULLSCREEN
            17: 1040,  # SM_CYFULLSCREEN
            18: 17,    # SM_CYKANJIWINDOW
            19: 1,     # SM_MOUSEPRESENT
            20: 0,     # SM_SWAPBUTTON
            21: 4,     # SM_CXMIN
            22: 4,     # SM_CYMIN
            23: 0,     # SM_DEBUG
            28: 0,     # SM_MOUSEWHEELPRESENT
            32: 8,     # SM_CXFRAME / SM_CXSIZEFRAME
            33: 8,     # SM_CYFRAME / SM_CYSIZEFRAME
            34: 2,     # SM_CXMINTRACK
            35: 2,     # SM_CYMINTRACK
            36: 0,     # SM_CXDOUBLECLK
            37: 0,     # SM_CYDOUBLECLK
            38: 75,    # SM_CXICONSPACING
            39: 75,    # SM_CYICONSPACING
            40: 0,     # SM_MENUDROPALIGNMENT
            41: 0,     # SM_PENWINDOWS
            42: 0,     # SM_DBCSENABLED
            43: 1,     # SM_CMOUSEBUTTONS
            44: 0,     # SM_CLEANBOOT: 0 means normal boot, not safe mode.
            67: 3,     # SM_NETWORK: low bit set means network present.
            70: 0,     # SM_SHOWSOUNDS
            75: 0,     # SM_MOUSEHORIZONTALWHEELPRESENT
            76: 0,     # SM_XVIRTUALSCREEN
            77: 0,     # SM_YVIRTUALSCREEN
            78: 1920,  # SM_CXVIRTUALSCREEN
            79: 1080,  # SM_CYVIRTUALSCREEN
            80: 1,     # SM_CMONITORS
            81: 1,     # SM_SAMEDISPLAYFORMAT
            82: 1,     # SM_IMMENABLED
            83: 1,     # SM_CXFOCUSBORDER
            84: 1,     # SM_CYFOCUSBORDER
            86: 0,     # SM_TABLETPC
            87: 0,     # SM_MEDIACENTER
            88: 0,     # SM_STARTER
            89: 0,     # SM_SERVERR2
            91: 4,     # SM_CXPADDEDBORDER
            4096: 0,   # SM_REMOTESESSION
            8193: 0,   # SM_REMOTECONTROL
        }
        argv[0] = nIndex
        return metrics.get(nIndex, 1)

"""
    if old in text:
        text = text.replace(old, new, 1)
    elif "def GetSystemMetrics(self, emu, argv, ctx={}):" in text and "SM_CXSCREEN" not in text:
        raise RuntimeError(f"GetSystemMetrics patch anchor drifted in {user32}")
    user32.write_text(text, encoding="utf-8")


