    def _sx_write_monitor_info(self, emu, lpmi, wide=False):
        if not lpmi:
            return
        try:
            cb_size = int.from_bytes(self.mem_read(lpmi, 4), 'little')
        except Exception:
            cb_size = 40
        cb_size = max(cb_size, 40)
        rects = (
            (0).to_bytes(4, 'little', signed=True)
            + (0).to_bytes(4, 'little', signed=True)
            + (1920).to_bytes(4, 'little', signed=True)
            + (1080).to_bytes(4, 'little', signed=True)
            + (0).to_bytes(4, 'little', signed=True)
            + (0).to_bytes(4, 'little', signed=True)
            + (1920).to_bytes(4, 'little', signed=True)
            + (1040).to_bytes(4, 'little', signed=True)
            + (1).to_bytes(4, 'little')
        )
        self.mem_write(lpmi, cb_size.to_bytes(4, 'little') + rects)
        name = '\\\\.\\DISPLAY1'
        raw_name = name.encode('utf-16le') + b'\\x00\\x00' if wide else name.encode('ascii') + b'\\x00'
        name_off = 40
        if cb_size > name_off:
            self.mem_write(lpmi + name_off, raw_name[: max(0, cb_size - name_off)])

