def patch_shlwapi_wvnsprintf_guard() -> None:
    shlwapi = _speakeasy_root() / "winenv" / "api" / "usermode" / "shlwapi.py"
    text = shlwapi.read_text(encoding="utf-8")

    old = """    @apihook('wvnsprintfA', argc=4)
    def wvnsprintfA(self, emu, argv, ctx={}):
        \"\"\"
        int wvnsprintfA(
            PSTR    pszDest,
            int     cchDest,
            PCSTR   pszFmt,
            va_list arglist
        );
        \"\"\"
        buffer, count, _format, argptr = argv
        rv = 0

        fmt_str = self.read_mem_string(_format, 1)
        fmt_cnt = self.get_va_arg_count(fmt_str)

        vargs = self.va_args(argptr, fmt_cnt)

        fin = self.do_str_format(fmt_str, vargs)
        fin = fin[:count] + '\\x00'

        rv = len(fin)
        self.mem_write(buffer, fin.encode('utf-8'))
        argv[0] = fin.replace('\\x00', '')
        argv[1] = fmt_str

        return rv

"""
    new = """    @apihook('wvnsprintfA', argc=4)
    def wvnsprintfA(self, emu, argv, ctx={}):
        \"\"\"
        int wvnsprintfA(
            PSTR    pszDest,
            int     cchDest,
            PCSTR   pszFmt,
            va_list arglist
        );
        \"\"\"
        buffer, count, _format, argptr = argv
        count &= 0xFFFFFFFF
        if not buffer or not count:
            return 0

        try:
            fmt_str = self.read_mem_string(_format, 1) if _format else ''
        except Exception:
            # Speakeasy overlay: malformed format pointers are common in
            # packed code paths; return an empty formatted string.
            fmt_str = ''

        try:
            fmt_cnt = self.get_va_arg_count(fmt_str)
            vargs = self.va_args(argptr, fmt_cnt) if fmt_cnt else []
            fin = self.do_str_format(fmt_str, vargs) if fmt_cnt else fmt_str
        except Exception:
            fin = fmt_str

        fin = fin[:max(count - 1, 0)]
        try:
            self.mem_write(buffer, (fin + '\\x00').encode('utf-8'))
        except Exception:
            pass
        argv[0] = fin
        argv[1] = fmt_str

        return len(fin)

"""
    if old in text:
        text = text.replace(old, new, 1)
    elif "Speakeasy overlay: malformed format pointers" not in text:
        raise RuntimeError(f"wvnsprintfA patch anchor not found in {shlwapi}")
    shlwapi.write_text(text, encoding="utf-8")


