def patch_shlwapi_string_number_helpers() -> None:
    shlwapi = _speakeasy_root() / "winenv" / "api" / "usermode" / "shlwapi.py"
    text = shlwapi.read_text(encoding="utf-8")

    marker = "    @apihook('PathAppend', argc=2)\n"
    handler = """    def _sx_str_to_int_ex(self, emu, argv, ctx={}):
        pszString, dwFlags, piRet = argv
        cw = self.get_char_width(ctx)
        try:
            text = self.read_mem_string(pszString, cw) if pszString else ''
        except Exception:
            text = ''
        argv[0] = text
        s = (text or '').strip()
        base = 16 if s.lower().startswith('0x') else 10
        try:
            value = int(s, base)
        except Exception:
            value = 0
        if piRet:
            try:
                self.mem_write(piRet, (value & 0xFFFFFFFF).to_bytes(4, 'little'))
            except Exception:
                pass
        return 1

    @apihook('StrToIntEx', argc=3)
    def StrToIntEx(self, emu, argv, ctx={}):
        return self._sx_str_to_int_ex(emu, argv, ctx)

    @apihook('StrToIntExA', argc=3)
    def StrToIntExA(self, emu, argv, ctx={}):
        return self._sx_str_to_int_ex(emu, argv, ctx)

    @apihook('StrToIntExW', argc=3)
    def StrToIntExW(self, emu, argv, ctx={}):
        return self._sx_str_to_int_ex(emu, argv, ctx)

    def _sx_str_trim(self, emu, argv, width):
        psz, pszTrimChars = argv
        if not psz:
            return 0
        try:
            text = self.read_mem_string(psz, width)
        except Exception:
            text = ''
        try:
            trim_chars = self.read_mem_string(pszTrimChars, width) if pszTrimChars else ' \\t\\r\\n'
        except Exception:
            trim_chars = ' \\t\\r\\n'
        argv[0] = text
        argv[1] = trim_chars
        trimmed = text.strip(trim_chars or ' \\t\\r\\n')
        if trimmed != text:
            self.write_mem_string(trimmed, psz, width)
            argv[0] = trimmed
            return 1
        return 0

    @apihook('StrTrim', argc=2)
    def StrTrim(self, emu, argv, ctx={}):
        return self._sx_str_trim(emu, argv, self.get_char_width(ctx))

    @apihook('StrTrimA', argc=2)
    def StrTrimA(self, emu, argv, ctx={}):
        return self._sx_str_trim(emu, argv, 1)

    @apihook('StrTrimW', argc=2)
    def StrTrimW(self, emu, argv, ctx={}):
        return self._sx_str_trim(emu, argv, 2)

    def _sx_str_rchr(self, argv, width):
        pszStart, pszEnd, wMatch = argv
        if not pszStart:
            return 0
        try:
            text = self.read_mem_string(pszStart, width)
        except Exception:
            text = ''
        if pszEnd and pszEnd > pszStart:
            max_chars = max(0, (pszEnd - pszStart) // width)
            text = text[:max_chars]
        ch = chr((wMatch & 0xFFFF) if width == 2 else (wMatch & 0xFF))
        argv[0] = text
        idx = text.rfind(ch)
        if idx < 0:
            return 0
        return pszStart + (idx * width)

    @apihook('StrRChrA', argc=3)
    def StrRChrA(self, emu, argv, ctx={}):
        return self._sx_str_rchr(argv, 1)

    @apihook('StrRChrW', argc=3)
    def StrRChrW(self, emu, argv, ctx={}):
        return self._sx_str_rchr(argv, 2)

    @apihook('StrChrA', argc=2)
    def StrChrA(self, emu, argv, ctx={}):
        pszStart, wMatch = argv
        if not pszStart:
            return 0
        try:
            text = self.read_mem_string(pszStart, 1)
        except Exception:
            text = ''
        ch = chr(wMatch & 0xFF)
        idx = text.find(ch)
        return pszStart + idx if idx >= 0 else 0

    @apihook('StrChrW', argc=2)
    def StrChrW(self, emu, argv, ctx={}):
        pszStart, wMatch = argv
        if not pszStart:
            return 0
        try:
            text = self.read_mem_string(pszStart, 2)
        except Exception:
            text = ''
        ch = chr(wMatch & 0xFFFF)
        idx = text.find(ch)
        return pszStart + (idx * 2) if idx >= 0 else 0

"""
    text = _insert_once(text, "def StrToIntEx(", marker, handler, shlwapi)
    shlwapi.write_text(text, encoding="utf-8")


