def patch_shell32_icon_helpers() -> None:
    shell32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "shell32.py"
    text = shell32.read_text(encoding="utf-8")

    marker = "    @apihook('ShellExecuteEx', argc=1)\n"
    handler = """    def _sx_shell_icon_handle(self):
        handle = getattr(self, '_sx_shell_icon_handle', 0x76040000)
        self._sx_shell_icon_handle = handle + 4
        return handle

    @apihook('ExtractIconEx', argc=5)
    def ExtractIconEx(self, emu, argv, ctx={}):
        '''
        UINT ExtractIconEx(
          LPCTSTR lpszFile,
          int nIconIndex,
          HICON *phiconLarge,
          HICON *phiconSmall,
          UINT nIcons
        );
        '''
        lpszFile, nIconIndex, phiconLarge, phiconSmall, nIcons = argv
        cw = self.get_char_width(ctx)
        if lpszFile:
            try:
                argv[0] = self.read_mem_string(lpszFile, cw)
            except Exception:
                pass
        if (nIconIndex & 0xFFFFFFFF) == 0xFFFFFFFF:
            return 4
        count = min(nIcons & 0xFFFFFFFF, 16)
        ptr_size = emu.get_ptr_size()
        for idx in range(count):
            if phiconLarge:
                try:
                    self.mem_write(phiconLarge + idx * ptr_size, self._sx_shell_icon_handle().to_bytes(ptr_size, 'little'))
                except Exception:
                    pass
            if phiconSmall:
                try:
                    self.mem_write(phiconSmall + idx * ptr_size, self._sx_shell_icon_handle().to_bytes(ptr_size, 'little'))
                except Exception:
                    pass
        return count

    @apihook('ExtractIconExA', argc=5)
    def ExtractIconExA(self, emu, argv, ctx={}):
        return self.ExtractIconEx(emu, argv, ctx)

    @apihook('ExtractIconExW', argc=5)
    def ExtractIconExW(self, emu, argv, ctx={}):
        return self.ExtractIconEx(emu, argv, ctx)

    @apihook('ExtractIcon', argc=3)
    def ExtractIcon(self, emu, argv, ctx={}):
        hInst, pszExeFileName, nIconIndex = argv
        return self._sx_shell_icon_handle()

    @apihook('ExtractIconA', argc=3)
    def ExtractIconA(self, emu, argv, ctx={}):
        return self.ExtractIcon(emu, argv, ctx)

    @apihook('ExtractIconW', argc=3)
    def ExtractIconW(self, emu, argv, ctx={}):
        return self.ExtractIcon(emu, argv, ctx)

"""
    text = _insert_once(text, "def ExtractIconEx(", marker, handler, shell32)
    shell32.write_text(text, encoding="utf-8")


