            header[0:4] = (40).to_bytes(4, 'little')
            header[4:8] = int(meta.get('width', 1)).to_bytes(4, 'little', signed=True)
            header[8:12] = int(meta.get('height', 1)).to_bytes(4, 'little', signed=True)
            header[12:14] = (1).to_bytes(2, 'little')
