        available = max(0, destsz - len(prefix) - 1)
        requested = 0x10000 if count == 0xFFFFFFFF else min(count, 0x10000)
        text = self._sx_read_safe_string(src, width, requested)
        truncated = len(text) > available
        out_text = (prefix + text[:available]) if append else text[:max(0, destsz - 1)]
        raw = out_text.encode('utf-16le') + b'\\x00\\x00' if width == 2 else out_text.encode('utf-8', errors='replace') + b'\\x00'
