    def _sx_ctype_bits(self, c):
        c &= 0xFF
        bits = 0
        if 65 <= c <= 90:
            bits |= 0x0001 | 0x0100
        if 97 <= c <= 122:
            bits |= 0x0002 | 0x0100
        if 48 <= c <= 57:
            bits |= 0x0004
        if c in (9, 10, 11, 12, 13, 32):
            bits |= 0x0008
        if c < 32 or c == 127:
            bits |= 0x0020
        if c in (9, 32):
            bits |= 0x0040
        if (48 <= c <= 57) or (65 <= c <= 70) or (97 <= c <= 102):
            bits |= 0x0080
        if 33 <= c <= 126 and not (bits & (0x0100 | 0x0004 | 0x0008)):
            bits |= 0x0010
        return bits

