    def _open(self, emu, argv, ctx={}):
        pathp, flags, mode = argv
        path = self.read_mem_string(pathp, 1) if pathp else ''
        argv[0] = path
        hnd = self._sx_crt_next_file()
        self._sx_crt_files()[hnd] = {'path': path, 'mode': str(flags), 'pos': 0, 'data': self._sx_crt_seed_data(path)}
        return hnd

