def patch_msvcrt_printf_guards() -> None:
    msvcrt = _speakeasy_root() / "winenv" / "api" / "usermode" / "msvcrt.py"
    text = msvcrt.read_text(encoding="utf-8")
    if "Speakeasy overlay: tolerate incomplete sprintf varargs" in text:
        return

    old_sprintf = """    @apihook('sprintf', argc=e_arch.VAR_ARGS, conv=e_arch.CALL_CONV_CDECL)
    def sprintf(self, emu, argv, ctx={}):
        \"\"\"
        int sprintf(
            char *buffer,
            const char *format [,
            argument] ...
            );
        \"\"\"
        buf, fmt = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 2)
        fmt_str = self.read_string(fmt)
        fmt_cnt = self.get_va_arg_count(fmt_str)
        if not fmt_cnt:
            self.write_string(fmt_str, buf)
            return len(fmt_str)

        _argv = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 2 + fmt_cnt)[2:]
        fin = self.do_str_format(fmt_str, _argv)

        self.write_string(fin, buf)
        argv.clear()
        argv.append(fin)
        return len(fin)

"""
    new_sprintf = """    @apihook('sprintf', argc=e_arch.VAR_ARGS, conv=e_arch.CALL_CONV_CDECL)
    def sprintf(self, emu, argv, ctx={}):
        \"\"\"
        int sprintf(
            char *buffer,
            const char *format [,
            argument] ...
            );
        \"\"\"
        buf, fmt = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 2)
        try:
            fmt_str = self.read_string(fmt) if fmt else ''
        except Exception:
            # Speakeasy overlay: tolerate incomplete sprintf varargs.
            fmt_str = ''
        try:
            fmt_cnt = self.get_va_arg_count(fmt_str)
            _argv = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 2 + fmt_cnt)[2:] if fmt_cnt else []
            fin = self.do_str_format(fmt_str, _argv) if fmt_cnt else fmt_str
        except Exception:
            fin = fmt_str

        try:
            self.write_string(fin, buf)
        except Exception:
            pass
        argv.clear()
        argv.append(fin)
        return len(fin)

"""
    old_snprintf = """    @apihook('_snprintf', argc=e_arch.VAR_ARGS, conv=e_arch.CALL_CONV_CDECL)
    def _snprintf(self, emu, argv, ctx={}):
        \"\"\"
        int _snprintf(
        char *buffer,
        size_t count,
        const char *format [,
        argument] ...
        );
        \"\"\"
        buf, count, fmt = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 3)
        fmt_str = self.read_string(fmt)
        fmt_cnt = self.get_va_arg_count(fmt_str)
        if not fmt_cnt:
            self.write_string(fmt_str, buf)
            return len(fmt_str)

        _argv = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 3 + fmt_cnt)[3:]
        fin = self.do_str_format(fmt_str, _argv)

        self.write_string(fin, buf)
        argv.clear()
        argv.append(fin)
        return len(fin)

"""
    new_snprintf = """    @apihook('_snprintf', argc=e_arch.VAR_ARGS, conv=e_arch.CALL_CONV_CDECL)
    def _snprintf(self, emu, argv, ctx={}):
        \"\"\"
        int _snprintf(
        char *buffer,
        size_t count,
        const char *format [,
        argument] ...
        );
        \"\"\"
        buf, count, fmt = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 3)
        count &= 0xFFFFFFFF
        try:
            fmt_str = self.read_string(fmt) if fmt else ''
        except Exception:
            fmt_str = ''
        try:
            fmt_cnt = self.get_va_arg_count(fmt_str)
            _argv = emu.get_func_argv(e_arch.CALL_CONV_CDECL, 3 + fmt_cnt)[3:] if fmt_cnt else []
            fin = self.do_str_format(fmt_str, _argv) if fmt_cnt else fmt_str
        except Exception:
            fin = fmt_str
        if count:
            fin = fin[:max(count - 1, 0)]
        try:
            self.write_string(fin, buf)
        except Exception:
            pass
        argv.clear()
        argv.append(fin)
        return len(fin)

"""
    if old_sprintf not in text or old_snprintf not in text:
        raise RuntimeError(f"sprintf/_snprintf patch anchor not found in {msvcrt}")
    text = text.replace(old_sprintf, new_sprintf, 1).replace(old_snprintf, new_snprintf, 1)
    msvcrt.write_text(text, encoding="utf-8")


def patch_msvcrt_wide_printf_helpers() -> None:
    msvcrt = _speakeasy_root() / "winenv" / "api" / "usermode" / "msvcrt.py"
    text = msvcrt.read_text(encoding="utf-8")

    marker = "    @apihook('sprintf', argc=e_arch.VAR_ARGS, conv=e_arch.CALL_CONV_CDECL)\n"
