    @apihook('_vscprintf_l', argc=3, conv=e_arch.CALL_CONV_CDECL)
    def _vscprintf_l(self, emu, argv, ctx={}):
        fmt, locale, argptr = argv
        return self._vscprintf(emu, [fmt, argptr], ctx)

