            b'\\x8b\\x44\\x24' + bytes([stack_offset & 0xFF])
            + b'\\x85\\xc0'
            + b'\\x74' + bytes([len(writes)])
            + bytes(writes)
            + b'\\xb8' + int(ret_value & 0xFFFFFFFF).to_bytes(4, 'little')
            + b'\\xc2' + int(clean & 0xFFFF).to_bytes(2, 'little')
