        entries[2] = self._stub(emu, 1, 4, 'device.release')
        entries[3] = self._stub(emu, self.S_OK, 4, 'device.TestCooperativeLevel')
        entries[16] = self._stub(emu, self.S_OK, 8, 'device.Reset')
        entries[17] = self._stub(emu, self.S_OK, 20, 'device.Present')
        entries[41] = self._stub(emu, self.S_OK, 4, 'device.BeginScene')
