    @apihook('JLI_List_new', argc=1)
    def JLI_List_new(self, emu, argv, ctx={}):
        capacity, = argv
        capacity = max(4, min(int(capacity or 0) & 0xFFFFFFFF, 0x1000))
        ptr_size = emu.get_ptr_size()
        items = self.mem_alloc(capacity * ptr_size, tag='api.jli.list.items')
        obj = self.mem_alloc(0x20, tag='api.jli.list')
        self.mem_write(items, b'\\x00' * (capacity * ptr_size))
        self.mem_write(obj, self._ptr_bytes(emu, items) + (0).to_bytes(4, 'little') + capacity.to_bytes(4, 'little'))
        self._lists[obj] = {'items': items, 'count': 0, 'capacity': capacity, 'values': []}
        return obj

    @apihook('JLI_List_add', argc=2)
    def JLI_List_add(self, emu, argv, ctx={}):
        lst, value = argv
        cur = self._lists.get(lst)
        if cur and cur['count'] < cur['capacity']:
            off = cur['items'] + cur['count'] * emu.get_ptr_size()
            try:
                self.mem_write(off, self._ptr_bytes(emu, value))
                cur['values'].append(self._read_cstr(value))
                cur['count'] += 1
                self.mem_write(lst + emu.get_ptr_size(), cur['count'].to_bytes(4, 'little'))
            except Exception:
                pass
