from .. import api
class Winspool(api.ApiHandler):
    name = 'winspool'
    apihook = api.ApiHandler.apihook
    impdata = api.ApiHandler.impdata
    def __init__(self, emu):
        super(Winspool, self).__init__(emu)
        self.funcs = {}
        self.data = {}
        self._printer_handle = 0x77000000
        self._change_handle = 0x77001000
        super(Winspool, self).__get_hook_attrs__(self)

    def _ptr_bytes(self, emu, value):
        return int(value or 0).to_bytes(emu.get_ptr_size(), 'little')

    def _read_string(self, ptr, ctx):
        if not ptr:
            return ''
        try:
            return self.read_mem_string(ptr, self.get_char_width(ctx))
        except Exception:
            return ''

    def _write_string_or_size(self, emu, buf, size_ptr, text, ctx):
        cw = self.get_char_width(ctx)
        required = len(text) + 1
        size = 0
        if size_ptr:
            try:
                size = int.from_bytes(self.mem_read(size_ptr, 4), 'little')
            except Exception:
                size = 0
        if not buf or size < required:
            if size_ptr:
                try: self.mem_write(size_ptr, required.to_bytes(4, 'little'))
                except Exception: pass
            return 0
        raw = text.encode('utf-16le') + b'\\x00\\x00' if cw == 2 else text.encode('utf-8') + b'\\x00'
        try:
            self.mem_write(buf, raw)
            self.mem_write(size_ptr, required.to_bytes(4, 'little'))
        except Exception:
            pass
        return 1

    @apihook('PrinterProperties', argc=2)
    def PrinterProperties(self, emu, argv, ctx={}):
        return 0

    @apihook('OpenPrinter', argc=3)
    def OpenPrinter(self, emu, argv, ctx={}):
        name, phPrinter, defaults = argv
        argv[0] = self._read_string(name, ctx)
        if phPrinter:
            try: self.mem_write(phPrinter, self._ptr_bytes(emu, self._printer_handle))
            except Exception: pass
        return 1

