    def _set_qregexp(self, obj, pattern='', case_sensitivity=1, syntax=0):
        obj = obj or self._handle()
        setattr(self, '_sx_qregexps', getattr(self, '_sx_qregexps', {}))
        self._sx_qregexps[obj] = {
            'pattern': pattern or '',
            'case_sensitivity': int(case_sensitivity) if case_sensitivity is not None else 1,
            'syntax': int(syntax) if syntax is not None else 0,
            'last_index': -1,
            'last_length': -1,
        }
        return obj
    def _qregexp_state(self, obj):
        return getattr(self, '_sx_qregexps', {}).get(obj, {'pattern': '', 'case_sensitivity': 1, 'syntax': 0, 'last_index': -1, 'last_length': -1})
    def _qregexp_index(self, regexp, text, offset=0):
        state = self._qregexp_state(regexp)
        pattern = state.get('pattern') or ''
        try:
            offset = max(0, int(offset))
        except Exception:
            offset = 0
        haystack = text[offset:]
        flags = re.IGNORECASE if state.get('case_sensitivity') == 0 else 0
        idx, length = -1, -1
        if pattern:
            try:
                match = re.search(pattern, haystack, flags)
                if match:
                    idx, length = offset + match.start(), max(0, match.end() - match.start())
            except Exception:
                lhs = haystack.lower() if flags else haystack
                rhs = pattern.lower() if flags else pattern
                pos = lhs.find(rhs)
                if pos >= 0:
                    idx, length = offset + pos, len(pattern)
        state['last_index'] = idx
        state['last_length'] = length
        return idx
