def patch_mfc42_module() -> None:
    mfc42 = _speakeasy_root() / "winenv" / "api" / "usermode" / "mfc42.py"
    if mfc42.is_file() and "class Mfc42" in mfc42.read_text(encoding="utf-8"):
        return

    mfc42.write_text("""# Speakeasy overlay: minimal MFC42 support.
import speakeasy.winenv.arch as e_arch

from .. import api


class Mfc42(api.ApiHandler):
    \"\"\"Small MFC42 ordinal surface for installer and stealer samples.\"\"\"

    name = 'mfc42'
    apihook = api.ApiHandler.apihook
    impdata = api.ApiHandler.impdata

    def __init__(self, emu):
        super(Mfc42, self).__init__(emu)
        self.funcs = {}
        self.data = {}
        self._sx_module_state = 0
        super(Mfc42, self).__get_hook_attrs__(self)

    def _state(self, emu):
        if not self._sx_module_state:
            self._sx_module_state = self.mem_alloc(0x400, tag='api.mfc42.module_state')
            self.mem_write(self._sx_module_state, b'\\x00' * 0x400)
        return self._sx_module_state

    def _read_cstr(self, ptr):
        if not ptr:
            return ''
        try:
            return self.read_mem_string(ptr, 1)
        except Exception:
            return ''

    def _write_cstring_like(self, emu, obj, text):
        if not obj:
            return 0
        raw = (text or '').encode('utf-8', errors='ignore')[:0x2000] + b'\\x00'
        buf = self.mem_alloc(max(1, len(raw)), tag='api.mfc42.cstring')
        self.mem_write(buf, raw)
        ptr_size = emu.get_ptr_size()
        try:
            self.mem_write(obj, buf.to_bytes(ptr_size, 'little'))
            self.mem_write(obj + ptr_size, max(0, len(raw) - 1).to_bytes(ptr_size, 'little'))
            self.mem_write(obj + (ptr_size * 2), max(15, len(raw) - 1).to_bytes(ptr_size, 'little'))
        except Exception:
            pass
        return obj

    def _format_ansi(self, fmt, args):
        text = fmt or ''
        for arg in args:
            value = self._read_cstr(arg) if isinstance(arg, int) else str(arg)
            for marker in ('%s', '%S'):
                if marker in text:
                    text = text.replace(marker, value, 1)
                    break
            else:
                text = text + value
        return text

    def _this_ecx(self, emu):
        try:
            return emu.reg_read(e_arch.X86_REG_ECX)
        except Exception:
            return 0

    @apihook('ordinal_1576', argc=4, ordinal=1576)
    def ordinal_1576(self, emu, argv, ctx={}):
        # Ordinal 1576 is the MFC WinMain handoff in older MFC42 builds. The
        # real DLL drives CWinApp::InitInstance/message-loop internally; our
        # overlay cannot enter that framework code, so stop cleanly instead of
        # returning into import thunks that often use far-return glue.
        self.exit_process()
        return self._state(emu)

    @apihook('ordinal_823', argc=1, ordinal=823)
    def ordinal_823(self, emu, argv, ctx={}):
        size, = argv
        size = max(1, size & 0xFFFFFFFF)
        return self.mem_alloc(size, tag='api.mfc42.ordinal_823')

    @apihook('ordinal_535', argc=0, ordinal=535)
    def ordinal_535(self, emu, argv, ctx={}):
        # CString default constructor.
        return self._write_cstring_like(emu, self._this_ecx(emu), '')

    @apihook('ordinal_537', argc=1, ordinal=537)
    def ordinal_537(self, emu, argv, ctx={}):
        # CString(LPCSTR) constructor; ECX is the object, stack arg is source text.
        src, = argv
        text = self._read_cstr(src)
        argv[0] = text
        return self._write_cstring_like(emu, self._this_ecx(emu), text)

    @apihook('ordinal_540', argc=0, ordinal=540)
    def ordinal_540(self, emu, argv, ctx={}):
        # CString destructor.
        return self._this_ecx(emu)

    @apihook('ordinal_2818', argc=3, ordinal=2818)
    def ordinal_2818(self, emu, argv, ctx={}):
        # CString::Format-like legacy MFC export used by older GUI loaders.
        cstring_obj, fmt_ptr, arg0 = argv
        fmt = self._read_cstr(fmt_ptr)
        argv[1] = fmt
        text = self._format_ansi(fmt, [arg0])
        return self._write_cstring_like(emu, cstring_obj, text)
""", encoding="utf-8")


