def patch_msvcp60_module() -> None:
    msvcp60 = _speakeasy_root() / "winenv" / "api" / "usermode" / "msvcp60.py"
    if msvcp60.is_file() and "ostream_insert_cstr" in msvcp60.read_text(encoding="utf-8"):
        return

    msvcp60.write_text("""# Speakeasy overlay: minimal legacy MSVCP60 support.
from .. import api


class Msvcp60(api.ApiHandler):
    name = 'msvcp60'
    apihook = api.ApiHandler.apihook
    impdata = api.ApiHandler.impdata

    def __init__(self, emu):
        super(Msvcp60, self).__init__(emu)
        self.funcs = {}
        self.data = {}
        self._strings = {}
        super(Msvcp60, self).__get_hook_attrs__(self)

    def _read_cstr(self, ptr):
        if not ptr:
            return ''
        try:
            return self.read_mem_string(ptr, 1)
        except Exception:
            return ''

    def _alloc_cstr(self, text):
        raw = (text or '').encode('utf-8', errors='ignore')[:0x1000] + b'\\x00'
        buf = self.mem_alloc(max(1, len(raw)), tag='api.msvcp60.basic_string')
        self.mem_write(buf, raw)
        return buf, max(0, len(raw) - 1)

    def _init_basic_string(self, emu, this, text=''):
        if not this:
            return this
        ptr_size = emu.get_ptr_size()
        buf, size = self._alloc_cstr(text)
        self._strings[this] = {'text': text or '', 'buf': buf, 'size': size}
        try:
            # Legacy MSVC strings are pointer/size/capacity-like enough for most malware setup paths.
            self.mem_write(this, buf.to_bytes(ptr_size, 'little'))
            self.mem_write(this + ptr_size, size.to_bytes(ptr_size, 'little'))
            self.mem_write(this + (ptr_size * 2), max(size, 15).to_bytes(ptr_size, 'little'))
        except Exception:
            pass
        return this

    def _copy_basic_string(self, emu, this, other):
        src = self._strings.get(other, {})
        text = src.get('text', '')
        if not text and other:
            try:
                ptr = int.from_bytes(self.mem_read(other, emu.get_ptr_size()), 'little')
                text = self._read_cstr(ptr)
            except Exception:
                text = ''
        return self._init_basic_string(emu, this, text)

    @apihook('??0?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAE@XZ', argc=1)
    def basic_string_ctor_default(self, emu, argv, ctx={}):
        this, = argv
        return self._init_basic_string(emu, this, '')

    @apihook('??0?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAE@ABV?$allocator@D@1@@Z', argc=2)
    def basic_string_ctor_alloc(self, emu, argv, ctx={}):
        this, alloc = argv
        return self._init_basic_string(emu, this, '')

    @apihook('??0?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAE@PBDIABV?$allocator@D@1@@Z', argc=4)
    def basic_string_ctor_cstr_alloc(self, emu, argv, ctx={}):
        this, cstr, count, alloc = argv
        text = self._read_cstr(cstr)
        if count and count != 0xFFFFFFFF:
            text = text[:count & 0xFFFFFFFF]
        argv[1] = text
        return self._init_basic_string(emu, this, text)

    @apihook('??0?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAE@PBDABV?$allocator@D@1@@Z', argc=3)
    def basic_string_ctor_cstr_only_alloc(self, emu, argv, ctx={}):
        this, cstr, alloc = argv
        text = self._read_cstr(cstr)
        argv[1] = text
        return self._init_basic_string(emu, this, text)

    @apihook('??0?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAE@ABV01@@Z', argc=2)
    def basic_string_ctor_copy(self, emu, argv, ctx={}):
        this, other = argv
        return self._copy_basic_string(emu, this, other)

    @apihook('??1?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAE@XZ', argc=1)
    def basic_string_dtor(self, emu, argv, ctx={}):
        this, = argv
        self._strings.pop(this, None)
        return this

    @apihook('??4?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAEAAV01@ABV01@@Z', argc=2)
    def basic_string_assign(self, emu, argv, ctx={}):
        this, other = argv
        return self._copy_basic_string(emu, this, other)

    @apihook('??4?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QAEAAV01@PBD@Z', argc=2)
    def basic_string_assign_cstr(self, emu, argv, ctx={}):
        this, cstr = argv
        text = self._read_cstr(cstr)
        argv[1] = text
        return self._init_basic_string(emu, this, text)

    @apihook('?c_str@?$basic_string@DU?$char_traits@D@std@@V?$allocator@D@2@@std@@QBEPBDXZ', argc=1)
    def basic_string_c_str(self, emu, argv, ctx={}):
        this, = argv
        state = self._strings.get(this)
        if state and state.get('buf'):
            return state['buf']
        if not getattr(self, '_sx_empty_string', 0):
            self._sx_empty_string = self.mem_alloc(1, tag='api.msvcp60.empty_string')
            self.mem_write(self._sx_empty_string, b'\\x00')
        return self._sx_empty_string

    @apihook('??6std@@YAAAV?$basic_ostream@DU?$char_traits@D@std@@@0@AAV10@PBD@Z', argc=2)
    def ostream_insert_cstr(self, emu, argv, ctx={}):
        stream, text = argv
        try:
            argv[1] = self.read_mem_string(text, 1) if text else ''
        except Exception:
            pass
        return stream

    @apihook('??6std@@YAAAV?$basic_ostream@DU?$char_traits@D@std@@@0@AAV10@D@Z', argc=2)
    def ostream_insert_char(self, emu, argv, ctx={}):
        stream, ch = argv
        return stream

    @apihook('?endl@std@@YAAAV?$basic_ostream@DU?$char_traits@D@std@@@1@AAV21@@Z', argc=1)
    def ostream_endl(self, emu, argv, ctx={}):
        stream, = argv
        return stream
""", encoding="utf-8")


def patch_rpcrt4_server_helpers() -> None:
    rpcrt4 = _speakeasy_root() / "winenv" / "api" / "usermode" / "rpcrt4.py"
