def patch_secur32_lsa_helpers() -> None:
    secur32 = _speakeasy_root() / "winenv" / "api" / "usermode" / "secur32.py"
    text = secur32.read_text(encoding="utf-8")

    marker = "    @apihook('EncryptMessage', argc=4)\n"
    handler = """    def _sx_lsa_handle(self):
        hnd = getattr(self, '_sx_lsa_next_handle', 0xA5500000) + 4
        self._sx_lsa_next_handle = hnd
        return hnd

    def _sx_read_lsa_string(self, emu, ptr):
        if not ptr:
            return ''
        try:
            length = int.from_bytes(self.mem_read(ptr, 2), 'little')
            buf = int.from_bytes(self.mem_read(ptr + (8 if emu.get_ptr_size() == 8 else 4), emu.get_ptr_size()), 'little')
            if not buf:
                buf = int.from_bytes(self.mem_read(ptr + 4, emu.get_ptr_size()), 'little')
            if buf and length:
                return self.mem_read(buf, min(length, 512)).decode('ascii', errors='ignore').rstrip('\\x00')
        except Exception:
            pass
        return ''

    def _sx_lsa_package_id(self, name):
        key = (name or '').lower()
        if 'kerberos' in key:
            return 0x10001
        if 'msv1_0' in key or 'msv1' in key or 'ntlm' in key:
            return 0x10002
        if 'nego' in key:
            return 0x10003
        if 'schannel' in key:
            return 0x10004
        return 0x10000

    def _sx_security_table(self, emu):
        ptr = getattr(self, '_sx_security_table_ptr', 0)
        if ptr:
            return ptr
        ptr = self.mem_alloc(0x200, tag='api.secur32.security_table')
        self.mem_write(ptr, b'\\x00' * 0x200)
        self.mem_write(ptr, (1).to_bytes(4, 'little'))  # dwVersion
        self._sx_security_table_ptr = ptr
        return ptr

    @apihook('InitSecurityInterfaceA', argc=0)
    def InitSecurityInterfaceA(self, emu, argv, ctx={}):
        return self._sx_security_table(emu)

    @apihook('InitSecurityInterfaceW', argc=0)
    def InitSecurityInterfaceW(self, emu, argv, ctx={}):
        return self._sx_security_table(emu)

    @apihook('LsaConnectUntrusted', argc=1)
    def LsaConnectUntrusted(self, emu, argv, ctx={}):
        LsaHandle, = argv
        if LsaHandle:
            self.mem_write(LsaHandle, self._sx_lsa_handle().to_bytes(emu.get_ptr_size(), 'little'))
        return 0

    @apihook('LsaDeregisterLogonProcess', argc=1)
    def LsaDeregisterLogonProcess(self, emu, argv, ctx={}):
        return 0

    @apihook('LsaLookupAuthenticationPackage', argc=3)
    def LsaLookupAuthenticationPackage(self, emu, argv, ctx={}):
        LsaHandle, PackageName, AuthenticationPackage = argv
        name = self._sx_read_lsa_string(emu, PackageName)
        if name:
            argv[1] = name
        if AuthenticationPackage:
            self.mem_write(AuthenticationPackage, self._sx_lsa_package_id(name).to_bytes(4, 'little'))
        return 0

    @apihook('LsaCallAuthenticationPackage', argc=7)
    def LsaCallAuthenticationPackage(self, emu, argv, ctx={}):
        LsaHandle, AuthenticationPackage, ProtocolSubmitBuffer, SubmitBufferLength, ProtocolReturnBuffer, ReturnBufferLength, ProtocolStatus = argv
        response = 0
        response_len = 0
        if SubmitBufferLength and ProtocolSubmitBuffer:
            try:
                argv[2] = self.mem_read(ProtocolSubmitBuffer, min(SubmitBufferLength & 0xFFFFFFFF, 256)).hex()
            except Exception:
                pass
        if ProtocolReturnBuffer:
            self.mem_write(ProtocolReturnBuffer, response.to_bytes(emu.get_ptr_size(), 'little'))
        if ReturnBufferLength:
            self.mem_write(ReturnBufferLength, response_len.to_bytes(4, 'little'))
        if ProtocolStatus:
            self.mem_write(ProtocolStatus, (0).to_bytes(4, 'little'))
        return 0

    @apihook('LsaFreeReturnBuffer', argc=1)
    def LsaFreeReturnBuffer(self, emu, argv, ctx={}):
        return 0

"""
    text = _insert_once(text, "def LsaConnectUntrusted(", marker, handler, secur32)
    secur32.write_text(text, encoding="utf-8")


